package com.itheima;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * 项目启动类 —— 整个 Spring Boot 应用的入口
 *
 * <p>运行它（或 java -jar 打包后的 jar）就会启动内嵌 Tomcat，默认端口 8080：</p>
 * <pre>
 * 前台页面  http://localhost:8080/
 * 接口      http://localhost:8080/depts、/emps、/upload ...
 * </pre>
 *
 * 【@SpringBootApplication 其实是三个注解的组合】
 * <ol>
 *   <li>@SpringBootConfiguration —— 声明这是一个配置类（@Configuration 的特例）；</li>
 *   <li>@EnableAutoConfiguration —— 开启自动配置，Spring Boot 根据 classpath 上的依赖
 *       自动装配数据源、MyBatis、Tomcat、Jackson 等（这也是“零 XML 配置”的来源）；</li>
 *   <li>@ComponentScan —— 扫描<b>当前包及其子包</b>下的 @Component/@Service/@RestController 等。</li>
 * </ol>
 *
 * 【为什么启动类要放在 com.itheima 根包】
 * 因为 @ComponentScan 默认只扫描「启动类所在包 + 子包」，
 * 放到根包才能扫到 controller / service / mapper / config 等所有包。
 * 这也是新手最常见的“Bean 注入失败”原因之一。
 *
 * 【不需要写 @MapperScan 的原因】
 * 每个 Mapper 接口上都标了 @Mapper，MyBatis 的自动配置会逐个处理；
 * 如果不想每个都标，也可以在启动类上加 @MapperScan("com.itheima.mapper") 统一扫描。
 */
@SpringBootApplication
public class TliasWebManagementApplication {

	public static void main(String[] args) {
		// SpringApplication.run 会创建 Spring 容器、启动内嵌 Tomcat，并阻塞在这里
		SpringApplication.run(TliasWebManagementApplication.class, args);
	}

}

