package com.itheima.config;

import jakarta.annotation.PostConstruct;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/**
 * 阿里云 OSS 配置项（对应 application.yml 里的 aliyun.oss.*）
 *
 * <pre>
 * aliyun:
 *   oss:
 *     endpoint: oss-cn-hangzhou.aliyuncs.com
 *     bucket-name: tlias-xxx
 *     region: cn-hangzhou
 *     access-key-id: LTAI...
 *     access-key-secret: ****
 * </pre>
 *
 * 【@ConfigurationProperties 和 @Value 的区别】
 * - @Value("${aliyun.oss.endpoint}") 一个一个注入，字段多了很啰嗦；
 * - @ConfigurationProperties(prefix = "aliyun.oss") 按前缀批量绑定，
 *   会把 aliyun.oss.bucket-name 绑定到 bucketName（松散绑定：中划线 → 驼峰）。
 *
 * 【AK/SK 放哪】
 * 正式项目用环境变量或配置中心；本项目为了练习，放在工作目录下的
 * config/application.yml（已被 .gitignore 忽略，不会提交到仓库）。
 * 千万不要把 AccessKey 直接写进 src/main/resources/application.yml —— 那个文件是要入库的。
 */
@Data
@Slf4j
@Component
@ConfigurationProperties(prefix = "aliyun.oss")
public class AliyunOssProperties {

    /** Bucket 所在地域的访问域名，如 oss-cn-hangzhou.aliyuncs.com */
    private String endpoint;

    /** Bucket 名称 */
    private String bucketName;

    /** 地域 ID，如 cn-hangzhou */
    private String region;

    /** AccessKey ID（LTAI 开头） */
    private String accessKeyId;

    /** AccessKey Secret（只在创建时显示一次） */
    private String accessKeySecret;

    /**
     * 启动时打印一次配置状态，方便确认配置有没有生效
     *
     * 【注意】这里绝对不能把 secret 打印出来，只打印“有没有配”。
     */
    @PostConstruct
    public void check() {
        boolean filled = notBlank(endpoint) && notBlank(bucketName)
                && notBlank(accessKeyId) && notBlank(accessKeySecret);
        if (filled) {
            log.info("阿里云 OSS 配置已加载: endpoint={}, bucket={}, region={}, AK={}****",
                    endpoint, bucketName, region,
                    accessKeyId.length() > 8 ? accessKeyId.substring(0, 8) : accessKeyId);
        } else {
            log.warn("阿里云 OSS 配置不完整（endpoint/bucketName/accessKeyId/accessKeySecret 有空值），" +
                    "上传会失败。请在 tlias-web-management/config/application.yml 里补全。");
        }
    }

    private boolean notBlank(String s) {
        return s != null && !s.trim().isEmpty();
    }

}

