package com.itheima.config;

import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

import java.nio.file.Paths;

/**
 * Web 相关配置（目前只做一件事：把上传目录映射成可访问的 URL）
 *
 * <pre>
 * 文件落在  <工作目录>/uploads/2026/10/27/xxx.png
 * 对外访问  http://localhost:8080/uploads/2026/10/27/xxx.png
 * </pre>
 *
 * 【为什么需要它】
 * MultipartFile 只是把文件写到了磁盘，磁盘目录默认不在 Web 的静态资源路径里，
 * 浏览器访问 /uploads/** 会 404。要么把它挪到 static 下（不推荐，jar 部署后 static 是只读的），
 * 要么像这里一样注册一个资源处理器把 URL 前缀映射到磁盘目录。
 *
 * 【为什么不会影响原来的静态资源】
 * application.yml 里配的 spring.web.resources.static-locations 由 Spring Boot 自动配置，
 * 映射的是 /**；这里额外注册的是 /uploads/**，两者并存，互不覆盖。
 *
 * 【换成阿里云 OSS 后】
 * 文件有了公网 URL，这个类和 tlias.upload.dir 配置都可以删掉。
 */
@Slf4j
@Configuration
public class WebConfig implements WebMvcConfigurer {

    /** 上传根目录，默认 uploads（相对启动时的工作目录），可用 tlias.upload.dir 覆盖 */
    @Value("${tlias.upload.dir:uploads}")
    private String uploadDir;

    /**
     * 注册静态资源处理器
     *
     * <p>Paths.get(...).toAbsolutePath().normalize().toUri() 会把
     * Windows 的 D:/xxx/uploads（反斜杠形式也一样）转成 file:///D:/xxx/uploads/ 这种合法 URI
     * （反斜杠转正斜杠、末尾补 /），资源处理器要求的就是这种格式。</p>
     */
    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        String location = Paths.get(uploadDir).toAbsolutePath().normalize().toUri().toString();
        registry.addResourceHandler("/uploads/**").addResourceLocations(location);
        log.info("上传目录已映射: /uploads/** -> {}", location);
    }

}

