package com.itheima.controller;

import com.itheima.pojo.Dept;
import com.itheima.pojo.Result;
import com.itheima.service.DeptService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.List;

/**
 * 部门管理控制器（Web 层）
 *
 * <pre>
 * 对应《接口文档》第 1 章：
 * GET    /depts        1.1 部门列表查询
 * DELETE /depts?id=1   1.2 删除部门（id 走查询参数，不是路径参数！）
 * POST   /depts        1.3 添加部门（JSON 请求体）
 * GET    /depts/{id}   1.4 根据 ID 查询
 * PUT    /depts        1.5 修改部门（JSON 请求体）
 * </pre>
 *
 * 【这一层只做三件事】
 * 1. 接收参数（路径 / 查询 / JSON 体）并打印日志；
 * 2. 调用 Service；
 * 3. 用 Result 包成统一响应。
 * 业务判断与 SQL 都不写在这里。
 *
 * 【三个类注解】
 * - @RestController = @Controller + @ResponseBody，返回值直接序列化为 JSON；
 * - @RequestMapping("/depts") 给本类所有接口加统一前缀；
 * - @Slf4j 由 Lombok 生成 log 对象，用于打印日志。
 */
@Slf4j
@RestController
@RequestMapping("/depts")
public class DeptController {

    /** 注入业务接口（实现类是 DeptServiceImpl） */
    @Autowired
    private DeptService deptService;

    /**
     * 1.1 部门列表查询
     *
     * <p>GET /depts，无参数。</p>
     * <p>返回：{"code":1,"msg":"success","data":[{"id":1,"name":"学工部",...}]}</p>
     */
    @GetMapping
    public Result list() {
        log.info("查询部门列表");
        List<Dept> deptList = deptService.findAll();
        return Result.success(deptList);
    }

    /**
     * 1.2 删除部门
     *
     * <p>DELETE /depts?id=1</p>
     *
     * <p>【易错】这里的 id 是「查询参数」，所以方法参数不加 @PathVariable；
     * Spring MVC 会按参数名把 ?id=1 绑定到 Integer id。
     * 如果写成 @DeleteMapping("/{id}") 就变成另一套契约，与接口文档不符。</p>
     */
    @DeleteMapping
    public Result delete(Integer id) {
        log.info("根据id删除部门, id: {}", id);
        deptService.deleteById(id);
        return Result.success();
    }

    /**
     * 1.3 添加部门
     *
     * <p>POST /depts，请求体：{"name":"教研部"}</p>
     *
     * <p>@RequestBody：把请求体 JSON 反序列化成 Dept 对象。
     * 前端必须发 Content-Type: application/json，否则会 415（不支持的媒体类型）。</p>
     */
    @PostMapping
    public Result save(@RequestBody Dept dept) {
        log.info("新增部门, dept: {}", dept);
        deptService.save(dept);
        return Result.success();
    }

    /**
     * 1.4 根据 ID 查询部门（修改回显）
     *
     * <p>GET /depts/1</p>
     *
     * <p>@PathVariable 从 URL 路径里取 {id}；
     * 与 1.2 的查询参数正好形成对照，这也是面试常问的点。</p>
     */
    @GetMapping("/{id}")
    public Result getById(@PathVariable Integer id) {
        log.info("根据ID查询部门, id: {}", id);
        Dept dept = deptService.getById(id);
        return Result.success(dept);
    }

    /**
     * 1.5 修改部门
     *
     * <p>PUT /depts，请求体：{"id":1,"name":"教研部"}</p>
     *
     * <p>【为什么不是 PUT /depts/{id}】接口文档就是 PUT /depts + 请求体带 id，
     * 前后端按文档来；虽然 RESTful 更常见的是路径带 id，这里保留文档约定。</p>
     */
    @PutMapping
    public Result update(@RequestBody Dept dept) {
        log.info("修改部门, dept: {}", dept);
        deptService.update(dept);
        return Result.success();
    }

}

package com.itheima.controller;

import com.itheima.pojo.Emp;
import com.itheima.pojo.EmpQueryParam;
import com.itheima.pojo.PageResult;
import com.itheima.pojo.Result;
import com.itheima.service.EmpService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * 员工管理控制器
 *
 * <pre>
 * 对应《接口文档》第 2 章：
 * GET    /emps?name&gender&begin&end&page&pageSize   2.1 条件分页查询
 * GET    /emps/list                                  2.6 查询全部
 * POST   /emps                                       2.3 新增（含工作经历）
 * GET    /emps/{id}                                  2.4 根据 ID 查询（回显）
 * PUT    /emps                                       2.5 修改（含工作经历）
 * DELETE /emps?ids=1,2,3                             2.2 批量删除
 * </pre>
 *
 * 【顺带回顾：Spring MVC 四种接收参数的方式，本项目全都用到了】
 * 1. 路径参数：@PathVariable          → GET /emps/{id}
 * 2. 查询参数：@RequestParam / 直接接 → DELETE /emps?ids=...、DELETE /depts?id=...
 * 3. 请求体  ：@RequestBody            → POST /emps、PUT /emps
 * 4. 对象封装：POJO 直接做形参          → GET /emps 的 EmpQueryParam
 */
@Slf4j
@RestController
@RequestMapping("/emps")
public class EmpController {

    @Autowired
    private EmpService empService;

    /**
     * 2.1 员工列表查询（条件 + 分页）
     *
     * <pre>GET /emps?name=张&amp;gender=1&amp;begin=2007-09-01&amp;end=2022-09-01&amp;page=1&amp;pageSize=10</pre>
     *
     * <p>没有写 @RequestParam：Spring MVC 发现形参是一个自定义 POJO，
     * 就会把同名 query 参数逐个 set 进去（page、pageSize、name、gender、begin、end）。</p>
     */
    @GetMapping
    public Result page(EmpQueryParam empQueryParam) {
        log.info("员工条件分页查询, 参数: {}", empQueryParam);
        PageResult pageResult = empService.page(empQueryParam);
        return Result.success(pageResult);
    }

    /**
     * 2.6 查询全部员工（不分页）
     *
     * <p>【注意】/emps/list 与 /emps/{id} 不会冲突：
     * Spring MVC 匹配时，精确路径 /list 的优先级高于路径变量 /{id}。</p>
     */
    @GetMapping("/list")
    public Result listAll() {
        log.info("查询全部员工");
        List<Emp> list = empService.findAll();
        return Result.success(list);
    }

    /**
     * 2.3 新增员工
     *
     * <p>POST /emps，请求体里除了员工字段还带 exprList（工作经历数组），
     * Jackson 会自动把它反序列化成 List&lt;EmpExpr&gt;。</p>
     */
    @PostMapping
    public Result save(@RequestBody Emp emp) {
        log.info("新增员工, emp: {}", emp);
        empService.save(emp);
        return Result.success();
    }

    /**
     * 2.4 根据 ID 查询员工（修改回显）
     *
     * <p>返回员工基本信息 + exprList（工作经历），前端用它填充弹窗。</p>
     */
    @GetMapping("/{id}")
    public Result getById(@PathVariable Integer id) {
        log.info("根据ID查询员工, id: {}", id);
        Emp emp = empService.getById(id);
        return Result.success(emp);
    }

    /**
     * 2.5 修改员工（含工作经历）
     *
     * <p>PUT /emps，请求体里的 id 决定改谁；exprList 会整体重建（先删后插）。</p>
     */
    @PutMapping
    public Result update(@RequestBody Emp emp) {
        log.info("修改员工, emp: {}", emp);
        empService.update(emp);
        return Result.success();
    }

    /**
     * 2.2 删除员工（支持批量）
     *
     * <pre>DELETE /emps?ids=1,2,3</pre>
     *
     * <p>@RequestParam List&lt;Integer&gt; ids：Spring MVC 会把逗号分隔的字符串
     * 自动转成 List&lt;Integer&gt;（单个 id 也能转）。</p>
     *
     * <p>【易错】不加 @RequestParam 时，List 类型参数也默认按 query 参数绑定，
     * 但显式写上更清晰；如果写成 @RequestBody 就完全收不到（GET/DELETE 一般不带体）。</p>
     */
    @DeleteMapping
    public Result delete(@RequestParam List<Integer> ids) {
        log.info("批量删除员工, ids: {}", ids);
        empService.deleteByIds(ids);
        return Result.success();
    }
}

package com.itheima.controller;

import com.itheima.pojo.EmpJobData;
import com.itheima.pojo.Result;
import com.itheima.service.ReportService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

/**
 * 数据统计控制器（讲义 116~118 集）
 *
 * <pre>
 * GET /report/empJobData        116 员工职位分布   → {jobList, dataList}
 * GET /report/empGenderData     116 员工性别分布   → [{name, value}]
 * GET /report/studentCountData  117 班级学员人数   → [{name, value}]
 * GET /report/studentDegreeData 118 学员学历分布   → [{name, value}]
 * </pre>
 *
 * 【为什么单独建一个 ReportController，而不是塞进 EmpController】
 * 统计是按“报表”维度组织的，与员工 CRUD 的职责不同；
 * 以后再加班级/学员/薪资统计，都放这里，Controller 不会越写越肿。
 *
 * 【返回结构为什么是 List&lt;Map&gt;】
 * 图表数据没有固定实体（类目名 + 数值），用 Map 最直接；
 * 代价是接口文档里看不出字段，所以 OpenAPI 里给这几个接口补了示例。
 */
@Slf4j
@RestController
@RequestMapping("/report")
public class ReportController {

    @Autowired
    private ReportService reportService;

    /** 116 集：员工职位分布（两个平行数组，方便 ECharts 直接用） */
    @GetMapping("/empJobData")
    public Result empJobData() {
        log.info("统计：员工职位分布");
        EmpJobData data = reportService.empJobData();
        return Result.success(data);
    }

    /** 116 集：员工性别分布 */
    @GetMapping("/empGenderData")
    public Result empGenderData() {
        log.info("统计：员工性别分布");
        List<Map<String, Object>> data = reportService.empGenderData();
        return Result.success(data);
    }

    /** 117 集：班级学员人数（需要 class / student 两张表） */
    @GetMapping("/studentCountData")
    public Result studentCountData() {
        log.info("统计：班级学员人数");
        List<Map<String, Object>> data = reportService.studentCountData();
        return Result.success(data);
    }

    /** 118 集：学员学历分布 */
    @GetMapping("/studentDegreeData")
    public Result studentDegreeData() {
        log.info("统计：学员学历分布");
        List<Map<String, Object>> data = reportService.studentDegreeData();
        return Result.success(data);
    }

}

package com.itheima.controller;

import com.aliyun.oss.OSSException;
import com.itheima.pojo.Result;
import com.itheima.utils.AliyunOSSUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;
import java.util.UUID;

/**
 * 文件上传接口
 *
 * <pre>
 * POST /upload    Content-Type: multipart/form-data    表单字段名必须叫 file
 * → {"code":1,"msg":"success","data":"https://heimaproject-yzj.oss-cn-beijing.aliyuncs.com/tlias/2026/10/27/xxx.png"}
 * </pre>
 *
 * 【两种存储方式，用配置切换】
 * <pre>
 * tlias.upload.storage = oss     → 存阿里云 OSS，返回公网 URL（默认，讲义 OSS 那节）
 * tlias.upload.storage = local   → 存本机 uploads/ 目录，返回 /uploads/** 相对路径（讲义本地存储那节）
 * </pre>
 * 两种方式对前端完全透明：接口路径、参数名、返回结构都一样，只是 data 的内容不同。
 *
 * 【不变的部分】无论存哪，先把关这四件事：
 * 1. 有没有传文件；2. 是否超过 10MB；3. 后缀是不是图片；4. 用 UUID 重命名（避免同名覆盖）。
 */
@Slf4j
@RestController
public class UploadController {

    /** 允许的图片后缀 */
    private static final List<String> ALLOWED_EXT = List.of("jpg", "jpeg", "png", "gif", "webp", "bmp");

    /** 单文件上限 10MB，与 application.yml 的 multipart.max-file-size 一致 */
    private static final long MAX_SIZE = 10L * 1024 * 1024;

    /** 存储方式：oss（默认）/ local */
    @Value("${tlias.upload.storage:oss}")
    private String storage;

    /** 本地存储根目录（仅 storage=local 时使用） */
    @Value("${tlias.upload.dir:uploads}")
    private String uploadDir;

    /** OSS 工具类（storage=oss 时使用） */
    private final AliyunOSSUtils aliyunOSSUtils;

    public UploadController(AliyunOSSUtils aliyunOSSUtils) {
        this.aliyunOSSUtils = aliyunOSSUtils;
    }

    /**
     * 上传图片
     *
     * @param file 表单字段 file 对应的文件
     * @return data 是可直接访问的 URL（OSS 公网地址或 /uploads/** 相对路径）
     */
    @PostMapping("/upload")
    public Result upload(MultipartFile file) {
        // ---------- 1. 公共校验：空文件 / 大小 / 后缀 ----------
        if (file == null || file.isEmpty()) {
            return Result.error("请选择要上传的文件");
        }
        if (file.getSize() > MAX_SIZE) {
            return Result.error("图片不能超过 10MB");
        }
        String originalName = file.getOriginalFilename();
        String ext = getExtension(originalName);
        if (!ALLOWED_EXT.contains(ext)) {
            return Result.error("只允许上传图片：" + String.join(" / ", ALLOWED_EXT));
        }

        // ---------- 2. 按配置选择存储方式 ----------
        if ("local".equalsIgnoreCase(storage)) {
            return uploadToLocal(file, ext);
        }
        return uploadToOss(file);
    }

    /**
     * 上传到阿里云 OSS（讲义 OSS 那节）
     *
     * <p>核心就一句：ossClient.putObject(bucket, objectName, inputStream, metadata)，
     * 细节都在 AliyunOSSUtils 里；这里只负责把异常翻译成友好提示。</p>
     */
    private Result uploadToOss(MultipartFile file) {
        try {
            String url = aliyunOSSUtils.upload(file);
            return Result.success(url);
        } catch (IllegalStateException e) {
            // 配置缺失（没填 AK/SK）——自己的问题，给出明确指引
            log.warn("OSS 未配置，上传失败: {}", e.getMessage());
            return Result.error("OSS 未配置，请在 config/application.yml 中填写阿里云信息（或改用 tlias.upload.storage=local）");
        } catch (OSSException e) {
            // 服务端错误：AccessDenied / NoSuchBucket / InvalidAccessKeyId 等，运维排查用
            log.error("上传到 OSS 失败: {}", e.getErrorMessage(), e);
            return Result.error("上传到 OSS 失败：" + e.getErrorCode());
        } catch (IOException e) {
            log.error("读取上传文件失败: {}", file.getOriginalFilename(), e);
            return Result.error("文件上传失败，请稍后重试");
        }
    }

    /**
     * 上传到本机磁盘（讲义“文件上传-本地存储”那节）
     *
     * <p>存到 &lt;工作目录&gt;/uploads/yyyy/MM/dd/UUID.ext，
     * 由 WebConfig 把 /uploads/** 映射出去，返回相对路径。</p>
     */
    private Result uploadToLocal(MultipartFile file, String ext) {
        String newName = UUID.randomUUID().toString().replace("-", "") + "." + ext;
        String datePath = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy/MM/dd"));
        Path dir = Paths.get(uploadDir, datePath).toAbsolutePath().normalize();
        try {
            Files.createDirectories(dir);
            // 必须用绝对路径，否则 transferTo 相对路径会落到容器临时目录
            file.transferTo(dir.resolve(newName).toFile());
        } catch (IOException e) {
            log.error("本地保存文件失败: {}", file.getOriginalFilename(), e);
            return Result.error("文件上传失败，请稍后重试");
        }
        String url = "/uploads/" + datePath + "/" + newName;
        log.info("文件已保存到本地: {} -> {}（{} 字节）", file.getOriginalFilename(), url, file.getSize());
        return Result.success(url);
    }

    /** 取小写后缀；没有后缀返回空串（会被白名单拒绝） */
    private String getExtension(String filename) {
        if (filename == null) {
            return "";
        }
        int dot = filename.lastIndexOf('.');
        if (dot < 0 || dot == filename.length() - 1) {
            return "";
        }
        return filename.substring(dot + 1).toLowerCase(Locale.ROOT);
    }

}

