package com.itheima.exception;

/**
 * 业务异常（讲义 115 集：全局异常处理器）
 *
 * <p>用途：Service / Controller 里遇到“用户操作不合法”的情况时抛它，
 * 由 {@link GlobalExceptionHandler} 统一捕获并转成 {"code":0,"msg":"..."} 返回给前端。</p>
 *
 * <pre>
 * 例：
 * if (CollectionUtils.isEmpty(ids)) throw new BusinessException("请选择要删除的员工");
 * </pre>
 *
 * 【为什么要自定义异常，而不是直接 return Result.error】
 * - Service 层不应该返回 Result（Result 是 Web 层的协议），抛异常更干净；
 * - 异常可以被 @Transactional 感知，能触发回滚；
 * - 一处定义、全局统一处理，Controller 里不用写 try/catch。
 *
 * 【为什么继承 RuntimeException】
 * Spring 默认只对 RuntimeException 回滚事务；继承 RuntimeException 才能让
 * @Transactional 在业务失败时自动回滚（受检异常需要额外写 rollbackFor）。
 */
public class BusinessException extends RuntimeException {

    public BusinessException(String message) {
        super(message);
    }

    public BusinessException(String message, Throwable cause) {
        super(message, cause);
    }

}

package com.itheima.exception;

import com.itheima.pojo.Result;
import lombok.extern.slf4j.Slf4j;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.multipart.MaxUploadSizeExceededException;

/**
 * 全局异常处理器（讲义 115 集）
 *
 * <p>作用：把“五花八门的异常”统一翻译成前端认识的 {"code":0,"msg":"..."}，
 * 页面只需弹一行友好提示，而不是看到 500 和一大段 Java 堆栈。</p>
 *
 * 【三个注解的含义】
 * <ul>
 *   <li>@RestControllerAdvice = @ControllerAdvice + @ResponseBody，
 *       对所有 @RestController 生效，返回值直接序列化成 JSON；</li>
 *   <li>@ExceptionHandler(XxxException.class) 声明“我负责处理哪类异常”；</li>
 *   <li>同一个异常有多个处理器时，Spring 选**继承关系最接近**的那个。</li>
 * </ul>
 *
 * 【处理顺序（从具体到笼统）】
 * BusinessException              业务自己抛的，直接用它的 msg
 * DuplicateKeyException          唯一索引冲突（用户名/手机号/部门名重复）
 * DataIntegrityViolationException 数据不合法（比如 varchar(10) 塞了 11 个字）
 * MaxUploadSizeExceededException 上传文件超过 multipart 限制
 * MethodArgumentTypeMismatch     URL 里参数类型不对（?id=abc）
 * HttpMessageNotReadable         JSON 格式错误
 * MethodArgumentNotValid         @Valid 校验不通过（后续加 @Validated 时会用到）
 * Exception                      兜底：记日志，返回通用提示
 *
 * 【注意】日志里记完整堆栈，返回给前端只给一句话 ——
 * 堆栈给开发看，提示给用户看，两者不要混。
 */
@Slf4j
@RestControllerAdvice
public class GlobalExceptionHandler {

    /* ==================== 1. 业务异常（最常用） ==================== */
    @ExceptionHandler(BusinessException.class)
    public Result handleBusinessException(BusinessException e) {
        // 业务异常是可以预期的，用 warn 级别，不打堆栈，避免日志被刷屏
        log.warn("业务异常: {}", e.getMessage());
        return Result.error(e.getMessage());
    }

    /* ==================== 2. 唯一索引冲突 ==================== */
    @ExceptionHandler(DuplicateKeyException.class)
    public Result handleDuplicateKey(DuplicateKeyException e) {
        String raw = e.getMessage() == null ? "" : e.getMessage();
        log.warn("唯一约束冲突: {}", raw);

        // 数据库报错里会带索引名或列名，据此给出更具体的提示
        if (raw.contains("username")) {
            return Result.error("用户名已存在，请换一个");
        }
        if (raw.contains("phone")) {
            return Result.error("手机号已存在，请换一个");
        }
        if (raw.contains("dept") || raw.contains("name")) {
            return Result.error("名称已存在，不能重复");
        }
        return Result.error("数据已存在，不能重复添加");
    }

    /* ==================== 3. 数据不合法（长度/非空/类型） ==================== */
    @ExceptionHandler(DataIntegrityViolationException.class)
    public Result handleDataIntegrity(DataIntegrityViolationException e) {
        String raw = e.getMostSpecificCause() == null ? "" : e.getMostSpecificCause().getMessage();
        if (raw == null) {
            raw = "";
        }
        log.warn("数据不合法: {}", raw);

        if (raw.contains("Data too long")) {
            // 例如 dept.name 是 varchar(10)，输入 11 个字就会走到这里
            return Result.error("输入的内容太长，请缩短后重试（部门名/姓名最多 10 个字）");
        }
        if (raw.contains("cannot be null") || raw.contains("doesn't have a default value")) {
            return Result.error("有必填项没有填写，请检查后重试");
        }
        if (raw.contains("Out of range")) {
            return Result.error("数值超出允许范围，请检查后重试");
        }
        return Result.error("数据格式不正确，请检查后重试");
    }

    /* ==================== 4. 上传文件过大 ==================== */
    @ExceptionHandler(MaxUploadSizeExceededException.class)
    public Result handleMaxUploadSize(MaxUploadSizeExceededException e) {
        log.warn("上传文件超过限制: {}", e.getMessage());
        return Result.error("图片不能超过 10MB，请压缩后再上传");
    }

    /* ==================== 5. 参数类型不匹配（?id=abc） ==================== */
    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    public Result handleTypeMismatch(MethodArgumentTypeMismatchException e) {
        log.warn("参数类型不匹配: name={}, value={}", e.getName(), e.getValue());
        return Result.error("参数 " + e.getName() + " 格式不正确");
    }

    /* ==================== 6. 请求体 JSON 解析失败 ==================== */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    public Result handleNotReadable(HttpMessageNotReadableException e) {
        log.warn("请求体解析失败: {}", e.getMessage());
        return Result.error("请求体格式不正确，请检查 JSON 是否合法");
    }

    /* ==================== 7. 参数校验不通过（@Valid，后续可加） ==================== */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public Result handleValidException(MethodArgumentNotValidException e) {
        String msg = e.getBindingResult().getFieldErrors().stream()
                .findFirst()
                .map(err -> err.getField() + " " + err.getDefaultMessage())
                .orElse("请求参数不合法");
        log.warn("参数校验失败: {}", msg);
        return Result.error(msg);
    }

    /* ==================== 8. 兜底：谁也没接住的异常 ==================== */
    @ExceptionHandler(Exception.class)
    public Result handleException(Exception e) {
        // 这里必须打完整堆栈，否则线上出问题无从查起
        log.error("系统异常", e);
        return Result.error("服务器开小差了，请稍后再试");
    }

}

