package com.itheima.mapper;

import com.itheima.pojo.Dept;
import org.apache.ibatis.annotations.*;

import java.util.List;

/**
 * 部门数据访问接口（MyBatis 注解方式）
 *
 * <p>对应《接口文档》第 1 章：列表 / 删除 / 新增 / 详情 / 修改。</p>
 *
 * 【@Mapper 是什么】
 * 告诉 MyBatis：这是一个 Mapper 接口，启动时由 MyBatis 用动态代理生成实现类，
 * 并注册成 Spring Bean（所以 Service 里可以直接 @Autowired 注入）。
 * 另一种等价写法是在启动类上加 @MapperScan("com.itheima.mapper")。
 *
 * 【注解 SQL vs XML 怎么选】
 * - SQL 简单、不会变（比如这里的部门 CRUD）→ 注解，代码紧凑；
 * - 需要动态拼接（<if>、<foreach>）→ XML（见 EmpMapper.xml）。
 * 两种方式可以混用，本项目就是混用的。
 *
 * 【#{} 的底层】
 * #{} 会被编译成 PreparedStatement 的 ? 占位符，参数通过 setXxx 传入，
 * 因此能防 SQL 注入；对应地 ${} 是字符串拼接，除非拼表名/排序字段，否则不要用。
 *
 * 对应讲义：部门管理（第 77~83 集）。
 */
@Mapper
public interface DeptMapper {

    /**
     * 查询全部部门
     * <p>SQL：select id, name, create_time, update_time from dept</p>
     * <p>说明：这里显式列出字段而不是 select *，可读性好一些，也不会受表结构变化影响。</p>
     *
     * @return 部门列表，没有数据时返回空集合（不是 null）
     */
    @Select("select id, name, create_time, update_time from dept")
    List<Dept> findAll();

    /**
     * 根据 ID 删除部门
     * <p>注意：返回 void 而不是 int，因为 Service 层目前不判断“删了几行”；</p>
     * <p>如果想区分“id 不存在”，可以改成 int 接收受影响行数。</p>
     *
     * @param id 部门 ID
     */
    @Delete("delete from dept where id = #{id}")
    void deleteById(Integer id);

    /**
     * 新增部门
     * <p>createTime / updateTime 由 Service 层补全后传进来，不是数据库默认值。</p>
     * <p>这里没有加 @Options(useGeneratedKeys) —— 部门新增后不需要用到自增 id，
     * 但员工新增需要（要拿 id 去插工作经历），那里就必须回填。</p>
     *
     * @param dept 部门对象（name / createTime / updateTime 有值）
     */
    @Insert("insert into dept(name,create_time,update_time) values(#{name},#{createTime},#{updateTime})")
    void insert(Dept dept);

    /**
     * 根据 ID 查询部门（修改时的数据回显）
     *
     * @param id 部门 ID
     * @return 部门对象；不存在时返回 null
     */
    @Select("select id, name, create_time, update_time from dept where id = #{id}")
    Dept getById(Integer id);

    /**
     * 修改部门
     * <p>只更新 name 和 update_time：create_time 不允许改，id 作为条件。</p>
     *
     * @param dept 至少包含 id、name
     */
    @Update("update dept set name = #{name},update_time = #{updateTime} where id = #{id}")
    void update(Dept dept);

}

