package com.itheima.mapper;

import com.itheima.pojo.EmpExpr;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Select;

import java.util.List;

/**
 * 员工工作经历数据访问接口（对应表 emp_expr）
 *
 * <p>这张表是“从表”，所有操作都围绕 emp_id 展开：
 * 新增员工时批量插入、修改员工时先删后插、删除员工时先删子表。</p>
 *
 * 【为什么 insertBatch / deleteByEmpIds 没有注解】
 * 它们用的是 XML（src/main/resources/mapper/EmpExprMapper.xml），
 * 因为需要 &lt;foreach&gt; 拼批量 value 和 in (...) —— 注解里写 foreach 很难读。
 */
@Mapper
public interface EmpExprMapper {

    /**
     * 批量插入工作经历
     *
     * <p>XML 里拼成一条 SQL：insert into emp_expr(emp_id, begin, end, company, job) values (...),(...),(...)
     * 比循环单条插入少 N-1 次数据库往返。</p>
     *
     * <p>前提：调用前每条 EmpExpr 的 empId 已经设置好（Service 用主表回填的 id 赋值）。</p>
     *
     * @param exprList 工作经历列表（不能为空集合，空集合会拼出非法 SQL，所以 Service 里先判空）
     */
    void insertBatch(List<EmpExpr> exprList);

    /**
     * 根据员工 ID 查询工作经历（修改时的数据回显）
     *
     * <p>按 begin 升序返回，前端才能按时间顺序展示。</p>
     *
     * @param empId 员工 ID
     * @return 该员工的工作经历列表；没有则返回空集合
     */
    @Select("select * from emp_expr where emp_id = #{empId} order by begin")
    List<EmpExpr> getByEmpId(Integer empId);

    /**
     * 根据员工 ID 批量删除工作经历
     *
     * <p>两个场景：修改员工（先删旧的再插新的）、删除员工（必须先删子表再删主表）。
     * XML 用 &lt;foreach&gt; 拼 in (...)，一次删多条。</p>
     *
     * @param empIds 员工 ID 列表
     */
    void deleteByEmpIds(List<Integer> empIds);

}

package com.itheima.mapper;

import com.itheima.pojo.EmpLog;
import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;

/**
 * 员工操作日志数据访问接口（对应表 emp_log）
 *
 * <p>表结构：id / operate_time / info（info 为 varchar(2000) 的日志文本）</p>
 *
 * <p>唯一的调用方是 EmpLogServiceImpl（REQUIRES_NEW 独立事务），
 * 这样主业务回滚时日志依然会落库 —— 这是“事务传播行为”那个案例的核心。</p>
 */
@Mapper
public interface EmpLogMapper {

    /**
     * 插入一条操作日志
     *
     * <p>@Options(useGeneratedKeys = true, keyProperty = "id")：把自增主键回写到 empLog.id，
     * 主要用途是打日志时能带上日志自身 ID，便于排查。</p>
     *
     * @param empLog 日志对象（operateTime、info 必须有值；info 超长会被 Service 截断）
     */
    @Options(useGeneratedKeys = true, keyProperty = "id")
    @Insert("insert into emp_log(operate_time, info) values (#{operateTime}, #{info})")
    void insert(EmpLog empLog);

}

package com.itheima.mapper;

import com.itheima.pojo.Emp;
import com.itheima.pojo.EmpQueryParam;
import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;
import org.apache.ibatis.annotations.Select;

import java.util.List;

/**
 * 员工数据访问接口
 *
 * <p>对应《接口文档》第 2 章：
 * 2.1 列表查询 / 2.2 删除 / 2.3 新增 / 2.4 根据 ID 查询 / 2.5 修改 / 2.6 查询全部。</p>
 *
 * 【注解与 XML 混用】
 * - 简单 SQL 用注解：listAll()、getById()、insert()；
 * - 需要动态拼接的用 XML：list()（多个 &lt;if&gt;）、update()（&lt;set&gt;）、deleteByIds()（&lt;foreach&gt;），
 *   文件在 src/main/resources/mapper/EmpMapper.xml，namespace 必须等于本接口的全限定名。
 *
 * 【没有注解的方法怎么找到 SQL】
 * XML 里只要存在 id 与方法名相同的 &lt;select&gt;/&lt;update&gt;/&lt;delete&gt;，MyBatis 就能绑定，
 * 接口方法上不需要再写注解。
 */
@Mapper
public interface EmpMapper {

    /**
     * 2.1 员工列表查询（条件 + 分页）
     *
     * <p>分页不在这个方法里做：Service 先调 PageHelper.startPage(page, pageSize)，
     * PageHelper 用拦截器改写下一条 SQL —— 自动加 LIMIT，并额外生成一条 count 查询。</p>
     *
     * <p>SQL 在 EmpMapper.xml 的 &lt;select id="list"&gt;，三个要点：
     * 1. LEFT JOIN dept 取部门名（没有部门的员工也要能查出来，所以是 LEFT 不是 INNER）；
     * 2. 条件用 &lt;where&gt; + &lt;if&gt; 动态拼；
     * 3. 必须带 order by（update_time desc, id desc），否则翻页顺序不稳定、可能出现重复行。</p>
     *
     * @param empQueryParam 姓名 / 性别 / 入职区间等条件（page、pageSize 由 PageHelper 处理）
     * @return 当前页数据；真实类型是 Page（可强转后取 getTotal()）
     */
    List<Emp> list(EmpQueryParam empQueryParam);

    /**
     * 2.6 查询全部员工（不分页、不带条件）
     *
     * @return 所有员工
     */
    @Select("select * from emp")
    List<Emp> listAll();

    /**
     * 2.3 新增员工
     *
     * <p>【最关键的一行】@Options(useGeneratedKeys = true, keyProperty = "id")：
     * 插入后把数据库生成的自增主键回写到 emp.id，
     * 因为紧接着要用这个 id 去批量插入工作经历（emp_expr.emp_id）。</p>
     *
     * <p>create_time / update_time 由 Service 补全；
     * 这里不插 password，讲义的页面没有密码输入框。</p>
     *
     * @param emp 员工对象；方法返回后 emp.getId() 就有值了
     */
    @Options(useGeneratedKeys = true, keyProperty = "id")
    @Insert("insert into emp(username, name, gender, phone, job, salary, image, entry_date, dept_id, create_time, update_time) " +
            "values (#{username},#{name},#{gender},#{phone},#{job},#{salary},#{image},#{entryDate},#{deptId},#{createTime},#{updateTime})")
    void insert(Emp emp);

    /**
     * 2.4 根据 ID 查询员工（修改回显）
     *
     * <p>只查员工本身，不含工作经历；工作经历由 EmpExprMapper.getByEmpId 单独查，
     * 最后在 Service 层拼成一个完整的 Emp 返回。</p>
     *
     * @param id 员工 ID
     * @return 员工对象；不存在返回 null
     */
    @Select("select * from emp where id = #{id}")
