package com.itheima.pojo;

import lombok.Data;

import java.io.Serializable;

/**
 * 后端统一响应结果
 *
 * <pre>
 * 所有接口都返回这一层“壳”，前端只判断 code：
 *   {"code":1,"msg":"success","data": ...}    成功
 *   {"code":0,"msg":"错误提示","data": null}   业务失败
 * </pre>
 *
 * 【为什么要统一响应】
 * 1. 前端不用为每个接口写不同的解析逻辑，一个拦截器统一拆包（见 static/js/api.js）；
 * 2. 区分「业务失败」和「系统/网络失败」：业务失败仍然是 HTTP 200，靠 code=0 表达；
 * 3. 与《接口文档》的约定一致，Apifox 里可以按同一结构做响应校验。
 *
 * 【易错点】
 * - code 用 Integer 不用 int：留出 null 的可能，方便以后扩展；
 * - data 用 Object：既能放对象（Dept）、集合（List<Dept>）、分页对象（PageResult）；
 * - 业务代码不要自己 new Result()，统一用三个静态工厂方法。
 *
 * 对应讲义：接口规范 / 统一响应（部门管理阶段就定下的约定）。
 */
@Data
public class Result implements Serializable {

    /** 状态码：1 成功，0 失败（失败原因看 msg） */
    private Integer code;

    /** 提示信息：成功固定 "success"，失败是给用户看的文案 */
    private String msg;

    /** 业务数据：对象 / 集合 / 分页结果；新增、修改、删除成功时为 null */
    private Object data;

    /**
     * 成功但无数据：新增、修改、删除这类接口使用
     * 返回 {"code":1,"msg":"success","data":null}
     */
    public static Result success() {
        Result result = new Result();
        result.code = 1;
        result.msg = "success";
        return result;
    }

    /**
     * 成功且带数据：列表、详情、分页这类查询接口使用
     *
     * @param object 要返回给前端的数据（对象 / 集合 / PageResult）
     */
    public static Result success(Object object) {
        Result result = new Result();
        result.data = object;
        result.code = 1;
        result.msg = "success";
        return result;
    }

    /**
     * 业务失败：参数不合法、上传类型不对等场景
     * 返回 {"code":0,"msg":"只允许上传图片：...","data":null}
     *
     * @param msg 给用户看的错误文案（前端拦截器会直接弹 ElMessage.error）
     */
    public static Result error(String msg) {
        Result result = new Result();
        result.msg = msg;
        result.code = 0;
        return result;
    }

}

