 * </ol>
 *
 * <p>统一返回 [{name=..., value=...}] 的形状（职位统计除外，它要两个平行数组），
 * 前端拿到的就是图表的“类目 + 数值”，不用再加工。</p>
 */
public interface ReportService {

    /** 员工职位分布：返回 jobList + dataList 两个平行数组（缺人的职位补 0） */
    EmpJobData empJobData();

    /** 员工性别分布：[{name=男, value=25}, {name=女, value=6}] */
    List<Map<String, Object>> empGenderData();

    /** 班级学员人数：[{name=班级名, value=人数}] */
    List<Map<String, Object>> studentCountData();

    /** 学员学历分布：[{name=本科, value=18}] */
    List<Map<String, Object>> studentDegreeData();

}

package com.itheima.service.impl;

import com.itheima.mapper.DeptMapper;
import com.itheima.pojo.Dept;
import com.itheima.service.DeptService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 部门管理业务实现
 *
 * <p>对应讲义第 77~83 集。这一层很薄，主要是“补字段 + 调 Mapper”，
 * 但它示范了 Service 层的职责边界：Controller 不写业务、Mapper 不写业务。</p>
 *
 * 【为什么部门这几个方法没有 @Transactional】
 * 每个方法只操作 dept 一张表，本来就是单条 SQL，数据库会自动保证原子性，
 * 加事务没有坏处但也没必要。对比 EmpServiceImpl：那里一次操作两张表，就必须加。
 *
 * 【@Service 的作用】
 * 把当前类注册成 Spring Bean（默认 Bean 名 deptServiceImpl），
 * 这样 DeptController 里的 @Autowired DeptService 才能注入进来。
 */
@Service
public class DeptServiceImpl implements DeptService {

    /**
     * 注入 Mapper 的代理对象（MyBatis 根据 @Mapper 接口生成的实现）
     * 字段注入写法简单，课程里统一用它；严格项目更推荐构造器注入（便于测试、避免循环依赖）
     */
    @Autowired
    private DeptMapper deptMapper;

    /**
     * 1.1 查询全部部门
     * <p>没有任何业务逻辑，直接透传给 Mapper。</p>
     */
    @Override
    public List<Dept> findAll() {
        return deptMapper.findAll();
    }

    /**
     * 1.2 删除部门
     * <p>直接按 id 删除。生产环境这里通常要先检查该部门下是否还有员工：</p>
     * <pre>
     * if (empMapper.countByDeptId(id) &gt; 0) throw new RuntimeException("该部门下还有员工，不能删除");
     * </pre>
     * 本项目为了和讲义一致，未做该校验。
     */
    @Override
    public void deleteById(Integer id) {
        deptMapper.deleteById(id);
    }

    /**
     * 1.3 新增部门
     * <p>前端只传 name，两个时间字段由这里补全：
     * 不在 SQL 里写 now() 是为了让“谁是业务动作的发起者”更清晰，也方便测试时固定时间。</p>
     */
    @Override
    public void save(Dept dept) {
        //补全基础属性
        dept.setCreateTime(LocalDateTime.now());
        dept.setUpdateTime(LocalDateTime.now());
        //保存部门
        deptMapper.insert(dept);
    }

    /**
     * 1.4 根据 ID 查询部门（修改回显）
     * <p>查不到时返回 null，Controller 会包成 {"code":1,"data":null}。</p>
     */
    @Override
    public Dept getById(Integer id) {
        return deptMapper.getById(id);
    }

    /**
     * 1.5 修改部门
     * <p>只更新 name 和 updateTime；createTime 不动（创建时间不允许被改）。
     * 这里没有校验“id 是否存在”，传一个不存在的 id 会更新 0 行，但接口仍返回成功。</p>
     */
    @Override
    public void update(Dept dept) {
        //补全基础属性
        dept.setUpdateTime(LocalDateTime.now());
        //保存部门
        deptMapper.update(dept);
    }

}

package com.itheima.service.impl;

import com.itheima.mapper.EmpLogMapper;
import com.itheima.pojo.EmpLog;
import com.itheima.service.EmpLogService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * 员工操作日志实现 —— 事务传播行为（REQUIRES_NEW）的教科书式用法
 *
 * <p>【四种常见传播行为对比】</p>
 * <pre>
 * REQUIRED（默认）：有事务就加入，没有就新建      → 日志会跟着业务一起回滚（不满足需求）
 * REQUIRES_NEW   ：挂起外层事务，自己开一个新的    → 日志独立提交（本项目用这个）
 * NESTED         ：在外层事务里开保存点，可局部回滚 → 外层回滚时仍然会一起回滚
 * SUPPORTS       ：有事务就用，没有就不用事务      → 日志可能没有事务保护
 * </pre>
 *
 * <p>【实测验证】故意让新增员工失败（工作经历公司名超长），结果：
 * emp 表没多数据（回滚了），emp_log 表却多了一条（独立事务提交了）。</p>
 *
 * <p>【为什么不能在 EmpServiceImpl 里直接调 empLogMapper.insert】
 * 那样它和外层 save() 用的是同一个事务，回滚时日志会一起消失；
 * 必须“换一个 Bean 调用 + REQUIRES_NEW”，因为 Spring 的事务是基于代理的，
 * 同一个类内部自调用不会走代理，@Transactional 不生效。</p>
 */
@Slf4j
@Service
public class EmpLogServiceImpl implements EmpLogService {

    @Autowired
    private EmpLogMapper empLogMapper;

    /**
     * 记录一条操作日志（独立事务）
     *
     * <p>REQUIRES_NEW 的执行过程：
     * 1. Spring 发现外层已有事务 → 把它挂起（suspend）；
     * 2. 从连接池另取一个连接，开启全新事务；
     * 3. 插入日志并提交；
     * 4. 恢复外层事务，外层该回滚就回滚，互不影响。</p>
     *
     * <p>小细节：执行本方法时外层事务已经挂起，但外层可能已经执行过写操作并持有行锁，
     * 如果日志要写同一行数据，仍可能互相等待 —— 所以日志表要独立，不写业务表。</p>
     *
     * @param empLog 日志对象（operateTime、info）
     */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    @Override
    public void insertLog(EmpLog empLog) {
        // 表字段 info 是 varchar(2000)，超长直接截断，避免“记录日志”本身把业务带崩
        String info = empLog.getInfo();
        if (info != null && info.length() > 2000) {
            empLog.setInfo(info.substring(0, 2000));
        }
        empLogMapper.insert(empLog);
        log.info("已记录员工操作日志, id: {}", empLog.getId());
    }

}

package com.itheima.service.impl;

import com.github.pagehelper.Page;
import com.github.pagehelper.PageHelper;
import com.itheima.mapper.EmpExprMapper;
import com.itheima.mapper.EmpMapper;
import com.itheima.pojo.Emp;
import com.itheima.pojo.EmpExpr;
import com.itheima.pojo.EmpLog;
import com.itheima.pojo.EmpQueryParam;
import com.itheima.pojo.PageResult;
import com.itheima.service.EmpLogService;
import com.itheima.service.EmpService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.CollectionUtils;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 员工管理业务实现（本项目最核心的一个类）
 *
 * <p>对应讲义第 93~114 集 + 事务传播行为案例。这里同时用到：</p>
 * <ul>
 *   <li>PageHelper 分页（page 方法）</li>
 *   <li>主子表事务（save / update / deleteByIds）</li>
 *   <li>事务传播 REQUIRES_NEW（save 里写 emp_log）</li>
 *   <li>@Slf4j 日志（入参与关键结果都打印，方便排查）</li>
 * </ul>
 *
 * 【@Slf4j 从哪来】Lombok 编译期生成 <code>private static final Logger log = LoggerFactory.getLogger(当前类.class);</code>
 */
@Slf4j
@Service
public class EmpServiceImpl implements EmpService {

    /** 员工主表 Mapper */
    @Autowired
    private EmpMapper empMapper;

    /** 工作经历从表 Mapper */
    @Autowired
    private EmpExprMapper empExprMapper;

    /** 操作日志 Service（内部用 REQUIRES_NEW 独立事务） */
    @Autowired
    private EmpLogService empLogService;

    /**
     * 2.1 员工列表查询（条件 + 分页）
     *
     * <p>【PageHelper 的三个要点，也是最容易踩坑的地方】</p>
     * <ol>
     *   <li>startPage 只对「紧跟着的第一次查询」生效，中间不能插别的查询；</li>
     *   <li>它通过拦截器改写下一条 SQL：自动加 LIMIT，并另外生成一条 count(*) 查总数
     *       —— 所以控制台会看到两条 SQL，这是正常的；</li>
     *   <li>返回的 List 实际是 com.github.pagehelper.Page（ArrayList 的子类），
     *       强转后可以 getTotal()、getResult()。</li>
     * </ol>
     *
     * <p>application.yml 里配了 reasonable: true —— 页码越界会自动纠正到最后一页，
     * 所以传 page=99 也不会返回空列表。</p>
     */
    @Override
    public PageResult page(EmpQueryParam empQueryParam) {
        //1. 设置PageHelper分页参数（page 从 1 开始，pageSize 每页条数）
        PageHelper.startPage(empQueryParam.getPage(), empQueryParam.getPageSize());
        //2. 执行查询：真正的 SQL 在 EmpMapper.xml 的 <select id="list">
        List<Emp> empList = empMapper.list(empQueryParam);
        //3. 强转成 Page 拿到总数，再封装成只含 total + rows 的 PageResult 返回前端
        Page<Emp> p = (Page<Emp>) empList;
        log.info("员工分页查询完成: total={}, 本页={}", p.getTotal(), p.getResult().size());
        return new PageResult(p.getTotal(), p.getResult());
    }

    /**
     * 2.6 查询全部员工（不分页）
     * <p>对应 GET /emps/list，一般给下拉框、导出等场景用。</p>
     */
    @Override
    public List<Emp> findAll() {
        List<Emp> list = empMapper.listAll();
        log.info("查询全部员工, 共 {} 条", list.size());
        return list;
    }

    /**
     * 2.3 新增员工（含工作经历 + 操作日志）
     *
     * <p>【事务】@Transactional(rollbackFor = Exception.class)：</p>
     * <ul>
     *   <li>一次操作 emp、emp_expr 两张表，必须同生共死；</li>
     *   <li>rollbackFor = Exception.class 是为了让「受检异常」也回滚
     *       （Spring 默认只回滚 RuntimeException 和 Error）；</li>
     *   <li>实测：故意让工作经历插入失败，员工那条记录也会被回滚掉。</li>
     * </ul>
     *
     * <p>【日志为什么用 try/finally】需求是“成功失败都要留痕”。
     * 写在 finally 里保证异常时也执行；而 insertLog 内部是 REQUIRES_NEW 独立事务，
     * 所以即使外层回滚，日志也已经提交了。</p>
     *
     * <p>【执行顺序】业务抛异常 → finally 执行（日志在新事务提交）→ 异常继续抛 → 外层事务回滚。</p>
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void save(Emp emp) {
        try {
            //1.补全基础属性（新增时创建时间=修改时间=当前时间）
            emp.setCreateTime(LocalDateTime.now());
            emp.setUpdateTime(LocalDateTime.now());
            //2.保存员工基本信息：insert 时 useGeneratedKeys 会把自增 id 回填到 emp.id
            empMapper.insert(emp);

            //3. 保存员工的工作经历信息 - 批量
            Integer empId = emp.getId();               // 上一步回填的主键
            List<EmpExpr> exprList = emp.getExprList();
            if (!CollectionUtils.isEmpty(exprList)) {   // 空集合不能进 foreach，否则拼出非法 SQL
                exprList.forEach(empExpr -> empExpr.setEmpId(empId));  // 每条经历都挂到该员工下
                empExprMapper.insertBatch(exprList);                   // 一条 SQL 批量插入
            }
        } finally {
            //4. 记录操作日志（独立事务，成功失败都写）
            //   格式与讲义一致："新增员工:" + emp，方便在 emp_log 里一眼区分是哪种操作
            EmpLog empLog = new EmpLog(null, LocalDateTime.now(), "新增员工:" + emp);
            empLogService.insertLog(empLog);
        }
    }

    /**
     * 2.4 根据 ID 查询员工（修改回显）
     *
     * <p>两次查询：先查主表，再查从表；然后手动把工作经历塞回 Emp 对象。
     * 这里没有用 MyBatis 的 &lt;collection&gt; 嵌套查询，因为分两步写更直观、也避免 N+1 问题。</p>
     *
     * @return 员工已不存在时返回 null（不会抛异常）
     */
    @Override
    public Emp getById(Integer id) {
        Emp emp = empMapper.getById(id);
        if (emp != null) {
            emp.setExprList(empExprMapper.getByEmpId(id));
        }
        return emp;
    }

    /**
     * 2.5 修改员工（含工作经历）
     *
     * <p>【工作经历为什么“先删后插”】前端改经历时可能增、删、改任意组合，
     * 逐条比对成本高；直接全部删掉再按提交的内容重建，逻辑最简单。
     * 代价是经历的 id 会变（前端不依赖它，所以无所谓）。</p>
     *
     * <p>整个过程在同一个事务里：删完还没插就失败的话，旧数据也会回滚回来。</p>
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void update(Emp emp) {
        //1. 补全修改时间
        emp.setUpdateTime(LocalDateTime.now());
        //2. 更新员工基本信息（XML 动态 SQL，只更新前端传了值的字段）
        empMapper.update(emp);
        //3. 删除该员工原有的工作经历（List.of 造一个单元素集合，复用批量删除方法）
        empExprMapper.deleteByEmpIds(List.of(emp.getId()));
        //4. 重新插入前端提交的工作经历
        List<EmpExpr> exprList = emp.getExprList();
        if (!CollectionUtils.isEmpty(exprList)) {
            exprList.forEach(empExpr -> empExpr.setEmpId(emp.getId()));
            empExprMapper.insertBatch(exprList);
        }
    }

    /**
     * 2.2 批量删除员工（含工作经历 + 操作日志）
     *
     * <p>【顺序】先删子表 emp_expr，再删主表 emp。
     * 讲义里写的是「先删 emp 再删 emp_expr」（因为项目用的是逻辑外键，没有物理约束，两种顺序都能跑通）；
     * 这里特意反过来：一旦哪天给 emp_expr.emp_id 加上物理外键，先删主表会直接报外键约束错误，
     * 先删子表则永远安全，也不会产生孤儿数据。</p>
     *
     * <p>【日志】和 save() 一样用 try/finally + REQUIRES_NEW 独立事务：
     * 删除成功要留痕，删除失败（比如后面哪天加了业务校验）也要留痕。</p>
     *
     * <p>ids 为空时直接 return：避免生成 <code>in ()</code> 这种非法 SQL（实测传空数组会 200 且什么都不删）。</p>
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void deleteByIds(List<Integer> ids) {
        if (CollectionUtils.isEmpty(ids)) {
            return;
        }
        try {
            //1. 删除工作经历（子表）
            empExprMapper.deleteByEmpIds(ids);
            //2. 删除员工（主表）
            empMapper.deleteByIds(ids);
        } finally {
            //3. 记录操作日志（独立事务：即使上面回滚，这条日志也已经提交）
            empLogService.insertLog(new EmpLog(null, LocalDateTime.now(), "删除员工:" + ids));
        }
    }
}

package com.itheima.service.impl;

import com.itheima.mapper.ReportMapper;
import com.itheima.pojo.EmpJobData;
import com.itheima.service.ReportService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 数据统计业务实现（讲义 116~118 集）
 *
 * 【这一层的主要工作：把数据库的“数字字典”翻译成中文】
 * 数据库里 job / gender / degree 存的都是 tinyint 编号，
 * 直接丢给前端，图表上就会显示 1、2、3 这种看不懂的类目名。
 * 所以统一在这里翻译成中文，前端只负责画图。
 *
 * 【用 LinkedHashMap 保证顺序】
 * 图表类目顺序要稳定，所以字典用 LinkedHashMap（插入顺序），
 * 不用 HashMap（迭代顺序不可预测，刷新页面柱子会乱跳）。
 */
@Slf4j
@Service
public class ReportServiceImpl implements ReportService {

    /** 职位字典：编号 → 中文（与 Emp.job 的注释保持一致） */
    private static final Map<Integer, String> JOB_MAP = new LinkedHashMap<>();
    /** 性别字典 */
    private static final Map<Integer, String> GENDER_MAP = new LinkedHashMap<>();
    /** 学历字典 */
    private static final Map<Integer, String> DEGREE_MAP = new LinkedHashMap<>();

    static {
        JOB_MAP.put(1, "班主任");
        JOB_MAP.put(2, "讲师");
        JOB_MAP.put(3, "学工主管");
        JOB_MAP.put(4, "教研主管");
        JOB_MAP.put(5, "咨询师");

        GENDER_MAP.put(1, "男");
        GENDER_MAP.put(2, "女");

        DEGREE_MAP.put(1, "初中");
        DEGREE_MAP.put(2, "高中");
        DEGREE_MAP.put(3, "大专");
        DEGREE_MAP.put(4, "本科");
        DEGREE_MAP.put(5, "硕士");
    }

    @Autowired
    private ReportMapper reportMapper;

    /**
     * 116 集：员工职位分布
     *
     * <p>SQL 只会返回“有人的职位”，比如只有讲师和班主任有人，
     * 那 jobList 就只有 2 个类目，图表会显得残缺。
     * 所以这里**按字典顺序遍历全部 5 个职位**，查不到的补 0，
     * 保证图表永远是 5 根柱子。</p>
     */
    @Override
    public EmpJobData empJobData() {
        List<Map<String, Object>> rows = reportMapper.countEmpByJob();

        // 先把查询结果转成 job 编号 -> 人数 的临时 Map，方便按字典遍历取值
        Map<Integer, Integer> countByJob = new LinkedHashMap<>();
        for (Map<String, Object> row : rows) {
            Integer job = toInteger(row.get("job"));
            Integer total = toInteger(row.get("total"));
            if (job != null) {
                countByJob.put(job, total == null ? 0 : total);
            }
        }

        List<String> jobList = new ArrayList<>();
        List<Integer> dataList = new ArrayList<>();
        for (Map.Entry<Integer, String> entry : JOB_MAP.entrySet()) {
            jobList.add(entry.getValue());
            dataList.add(countByJob.getOrDefault(entry.getKey(), 0));
        }

        log.info("员工职位分布统计: {}", dataList);
        return new EmpJobData(jobList, dataList);
    }

    /**
     * 116 集：员工性别分布
     *
     * <p>SQL 返回 [{name=1, value=25}, {name=2, value=6}]，
     * 这里把 name 换成“男/女”，键名保持 name/value 不变（前端直接能用）。</p>
     */
    @Override
    public List<Map<String, Object>> empGenderData() {
        List<Map<String, Object>> rows = reportMapper.countEmpByGender();
        List<Map<String, Object>> result = new ArrayList<>();

        for (Map<String, Object> row : rows) {
            Integer gender = toInteger(row.get("name"));
            Integer value = toInteger(row.get("value"));
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("name", GENDER_MAP.getOrDefault(gender, "未知"));
            item.put("value", value == null ? 0 : value);
            result.add(item);
        }

        log.info("员工性别分布统计: {}", result);
        return result;
    }

    /**
     * 117 集：班级学员人数
     * <p>班级名已经是中文，直接用；只在人数为 null 时补 0。</p>
     */
    @Override
    public List<Map<String, Object>> studentCountData() {
        List<Map<String, Object>> rows = reportMapper.countStudentByClazz();
        List<Map<String, Object>> result = new ArrayList<>();

