            item.put("name", DEGREE_MAP.getOrDefault(degree, "其他"));
            item.put("value", value == null ? 0 : value);
            result.add(item);
        }

        log.info("学员学历分布统计: {}", result);
        return result;
    }

    /**
     * 兜底转换：不同驱动/字段类型下，count 可能返回 Long、Integer 或 BigDecimal，
     * 统一转成 Integer，避免后面强转时分外脆弱。
     */
    private Integer toInteger(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number) {
            return ((Number) value).intValue();
        }
        try {
            return Integer.valueOf(value.toString());
        } catch (NumberFormatException e) {
            return null;
        }
    }

}

