package com.itheima.utils;

import com.aliyun.oss.OSS;
import com.aliyun.oss.OSSClientBuilder;
import com.aliyun.oss.OSSException;
import com.aliyun.oss.model.ObjectMetadata;
import com.itheima.config.AliyunOssProperties;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.io.InputStream;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.UUID;

/**
 * 阿里云 OSS 工具类（讲义：文件上传 - 阿里云 OSS）
 *
 * <pre>
 * 上传一张图片 → objectName = tlias/2026/10/27/853168a3.png
 *              → 返回       https://heimaproject-yzj.oss-cn-beijing.aliyuncs.com/tlias/2026/10/27/853168a3.png
 * </pre>
 *
 * 【OSS 的三个核心概念】
 * <ul>
 *   <li>Endpoint：Bucket 所在机房的访问域名，如 oss-cn-beijing.aliyuncs.com；</li>
 *   <li>Bucket  ：存储空间，名字全局唯一（相当于一个“网盘”）；</li>
 *   <li>Object  ：里面的每个文件，用 key（对象名）区分，可以有 “目录/” 前缀。</li>
 * </ul>
 *
 * 【为什么把 OSS 客户端做成单例】
 * OSSClient 内部维护了 HTTP 连接池，是线程安全的；每次都 new 一个会不断创建/销毁连接池，
 * 既慢又容易耗尽资源。所以这里在 @PostConstruct 里创建一次，应用关闭时 @PreDestroy 关掉。
 *
 * 【上传的关键 API】
 * <pre>
 * ossClient.putObject(bucketName, objectName, inputStream, objectMetadata);
 * </pre>
 * 第四个参数主要用来说明 Content-Type（图片要写 image/png 等，浏览器才会直接显示而不是下载）。
 */
@Slf4j
@Component
public class AliyunOSSUtils {

    /** 配置绑定类（endpoint / bucketName / accessKeyId / accessKeySecret） */
    private final AliyunOssProperties properties;

    /** OSS 客户端：单例，线程安全 */
    private OSS ossClient;

    /** 构造器注入：比字段 @Autowired 更推荐，便于测试、也避免循环依赖 */
    public AliyunOSSUtils(AliyunOssProperties properties) {
        this.properties = properties;
    }

    /**
     * 应用启动时创建 OSS 客户端
     *
     * <p>配置不全时不创建（ossClient 保持 null），这样本地开发即使没填 AK/SK
     * 也能正常启动，只是上传时会得到一条明确的错误提示。</p>
     */
    @PostConstruct
    public void init() {
        if (!isConfigured()) {
            log.warn("阿里云 OSS 未配置完整，OSS 上传不可用（请检查 tlias-web-management/config/application.yml）");
            return;
        }
        // 加 https:// 前缀：SDK 不加也能用，但显式写更清楚，避免被当成 http
        this.ossClient = new OSSClientBuilder().build(
                "https://" + properties.getEndpoint(),
                properties.getAccessKeyId(),
                properties.getAccessKeySecret());
        log.info("OSS 客户端已创建: bucket={}, endpoint={}", properties.getBucketName(), properties.getEndpoint());
    }

    /** 应用关闭时释放连接池 */
    @PreDestroy
    public void destroy() {
        if (ossClient != null) {
            ossClient.shutdown();
            log.info("OSS 客户端已关闭");
        }
    }

    /**
     * 上传文件到 OSS
     *
     * @param file 前端上传的文件（MultipartFile）
     * @return 可直接访问的公网 URL（前提是 Bucket 读权限为 public-read）
     * @throws IOException 读文件流出错
     * @throws OSSException OSS 服务端返回错误（AK 不对、Bucket 不存在、无权限等）
     */
    public String upload(MultipartFile file) throws IOException {
        if (ossClient == null) {
            throw new IllegalStateException("阿里云 OSS 未配置，无法上传（请填写 config/application.yml）");
        }

        String originalName = file.getOriginalFilename();
        String ext = getExtension(originalName);

        // 对象名：按天分目录 + UUID，避免同名覆盖，也让 Bucket 里不会一个目录堆几万个文件
        String datePath = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy/MM/dd"));
        String objectName = "tlias/" + datePath + "/"
                + UUID.randomUUID().toString().replace("-", "")
                + (ext.isEmpty() ? "" : "." + ext);

        // 元信息：Content-Type 决定浏览器是“直接显示”还是“下载”
        ObjectMetadata metadata = new ObjectMetadata();
        metadata.setContentType(file.getContentType());
        metadata.setContentLength(file.getSize());

        // try-with-resources：确保文件流被关闭
        try (InputStream in = file.getInputStream()) {
            ossClient.putObject(properties.getBucketName(), objectName, in, metadata);
        }

        String url = publicUrl(objectName);
        log.info("文件已上传到 OSS: {} -> {}（{} 字节）", originalName, url, file.getSize());
        return url;
    }

    /**
     * 拼公网访问地址
     *
     * <p>格式：https://{bucket}.{endpoint}/{objectName}
     * 注意是 bucket 作为子域名，不是 endpoint 后面接 bucket。</p>
     *
     * @param objectName OSS 里的对象名（key）
     */
    public String publicUrl(String objectName) {
        return "https://" + properties.getBucketName() + "." + properties.getEndpoint() + "/" + objectName;
    }

    /** 删除对象（测试或后续“删除员工时清理头像”会用到） */
    public void delete(String objectName) {
        if (ossClient == null) {
            return;
        }
        ossClient.deleteObject(properties.getBucketName(), objectName);
        log.info("已删除 OSS 对象: {}", objectName);
    }

    /** 配置是否完整 */
    private boolean isConfigured() {
        return notBlank(properties.getEndpoint())
                && notBlank(properties.getBucketName())
                && notBlank(properties.getAccessKeyId())
                && notBlank(properties.getAccessKeySecret());
    }

    private boolean notBlank(String s) {
        return s != null && !s.trim().isEmpty();
    }

    /** 取小写后缀，没有后缀返回空串 */
    private String getExtension(String filename) {
        if (filename == null) {
            return "";
        }
        int dot = filename.lastIndexOf('.');
        if (dot < 0 || dot == filename.length() - 1) {
            return "";
        }
        return filename.substring(dot + 1).toLowerCase(Locale.ROOT);
    }

}

