package com.itheima;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 获取请求数据的控制器
 * <p>
 * 【讲义 2.2.2 原文】Web 服务器（Tomcat）对 HTTP 协议的请求数据进行解析，
 * 并进行了封装（HttpServletRequest），并在调用 Controller 方法的时候传递给了该方法。
 * 这样，就使得程序员不必直接对协议进行操作，让 Web 开发更加便捷。
 * <p>
 * ======================== 这段代码演示了什么？========================
 * <p>
 * 讲义第 2 章讲的是 HTTP 协议本身：请求行、请求头、请求体长什么样。
 * 但实际开发中我们不用自己去解析这些原始报文 —— Tomcat 已经把它们解析好，
 * 封装成一个 {@link HttpServletRequest} 对象。
 * <p>
 * 我们只要把这个对象写在方法形参上，SpringMVC 就会把它传进来，
 * 然后就能用各种 getXxx() 方法取出想要的信息。
 * <p>
 * 对照讲义 2.2.1 的请求报文格式：
 * <pre>
 * GET /brand/findAll?name=OPPO&amp;status=1 HTTP/1.1     ← 请求行
 * Host: localhost:8080                              ← 请求头
 * User-Agent: Mozilla/5.0 ...
 * Accept: text/html
 *                                                   ← 空行（标记请求头结束）
 * （GET 请求没有请求体）                              ← 请求体
 * </pre>
 * 下面代码里每一行 getXxx() 取的就是上面报文里的对应部分。
 * <p>
 * ⚠ 提示：这是「底层写法」，了解即可。实际开发中更常用的是直接写方法形参
 * （像 {@link HelloController#hello(String)} 那样），SpringMVC 会自动完成参数绑定。
 */
@RestController
public class RequestController {

    /**
     * 请求路径 <a href="http://localhost:8084/request?name=Tom&amp;age=18">http://localhost:8084/request?name=Tom&amp;age=18</a>
     *
     * @param request Tomcat 解析并封装好的请求对象，SpringMVC 会自动传进来
     * @return 固定返回 "request success"，用于确认请求处理成功
     */
    @RequestMapping("/request")
    public String request(HttpServletRequest request) {

        // ========== 1.获取请求参数（对应请求行里 ? 后面的部分）==========
        // 请求路径 http://localhost:8084/request?name=Tom&age=18
        String name = request.getParameter("name");
        String age = request.getParameter("age");
        System.out.println("name = " + name + ", age = " + age);

        // ========== 2.获取请求路径 ==========
        // getRequestURI()：只取资源路径部分        → /request
        // getRequestURL()：取完整 URL（含协议、主机）→ http://localhost:8084/request
        String uri = request.getRequestURI();
        String url = request.getRequestURL().toString();
        System.out.println("uri = " + uri);
        System.out.println("url = " + url);

        // ========== 3.获取请求方式 ==========
        // GET / POST / PUT / DELETE ...
        String method = request.getMethod();
        System.out.println("method = " + method);

        // ========== 4.获取请求头 ==========
        // 这里取 User-Agent，也就是浏览器版本标识
        // 【讲义 2.2.1】服务端可以根据请求头中的内容来获取客户端的相关信息，
        // 比如判断浏览器类型，从而解决浏览器兼容问题
        String header = request.getHeader("User-Agent");
        System.out.println("header = " + header);

        return "request success";
    }

}

