package com.itheima;

import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;

/**
 * 设置响应数据的控制器
 * <p>
 * 【讲义 2.3.3 原文】Web 服务器对 HTTP 协议的响应数据进行了封装（HttpServletResponse），
 * 并在调用 Controller 方法的时候传递给了该方法。
 * <p>
 * ======================== 本类演示了两种写法 ========================
 * <p>
 * 讲义给了两种方式设置响应数据，本类把它们做成了两个接口，方便对比：
 * <ul>
 *     <li>{@link #response(HttpServletResponse)}  —— 方式一：直接操作 Servlet 原生对象</li>
 *     <li>{@link #response2(HttpServletResponse)} —— 方式二：使用 Spring 提供的 ResponseEntity</li>
 * </ul>
 * <p>
 * 对照讲义 2.3.1 的响应报文格式：
 * <pre>
 * HTTP/1.1 401                                    ← 响应行（协议版本 + 状态码 + 状态码描述）
 * name: itcast                                    ← 响应头
 * Content-Type: text/html;charset=utf-8
 *                                                 ← 空行（标记响应头结束）
 * &lt;h1&gt;hello response&lt;/h1&gt;                        ← 响应体
 * </pre>
 * <p>
 * ⚠ 【讲义 2.3.3 提示原文】响应状态码和响应头如果没有特殊要求的话，通常不手动设定。
 * 服务器会根据请求处理的逻辑，自动设置响应状态码和响应头。
 * <p>
 * 也就是说：正常返回数据时，状态码自动就是 200，一般不用我们管；
 * 下面这种手动设置 401、手动加响应头的写法，只是<b>教学演示</b>，实际项目里很少这么写。
 */
@RestController
public class ResponseController {

    /**
     * 方式一：直接操作 {@link HttpServletResponse} 原生对象
     * <p>
     * 访问地址：<a href="http://localhost:8084/response">http://localhost:8084/response</a>
     * <p>
     * 期望结果：HTTP 状态码 401，响应头里有一个 {@code name: itcast}，
     * 响应体是 {@code <h1>hello response</h1>}
     * <p>
     * 注意方法返回值是 {@code void} —— 因为响应数据是我们自己用
     * {@code response.getWriter().write(...)} 写出去的，不需要 return。
     *
     * @param response Tomcat 封装好的响应对象，SpringMVC 自动传进来
     */
    @RequestMapping("/response")
    public void response(HttpServletResponse response) throws IOException {

        // 1.设置响应状态码
        //    401 表示「未授权」（讲义 2.3.2 只重点要求记住 200 / 404 / 500 三个状态码）
        response.setStatus(401);

        // 2.设置响应头（自定义了一个名叫 name 的响应头，值是 itcast）
        response.setHeader("name", "itcast");

        // 3.设置响应体
        //    先告诉浏览器「我发给你的是 html，编码用 utf-8」，避免中文乱码
        response.setContentType("text/html;charset=utf-8");
        response.setCharacterEncoding("utf-8");

        //    把 HTML 内容写进响应体
        response.getWriter().write("<h1>hello response</h1>");
    }

    /**
     * 方式二：使用 Spring 提供的 {@link ResponseEntity}
     * <p>
     * 访问地址：<a href="http://localhost:8084/response2">http://localhost:8084/response2</a>
     * <p>
     * 期望结果：与方式一完全一样（401 + name:itcast + HTML 内容），
     * 但写法上是「链式调用」，一行就把状态码、响应头、响应体都设好了。
     * <p>
     * 两种写法的区别：
     * <ul>
     *     <li>方式一：命令式，一步一步设置，需要自己拿到 response 对象</li>
     *     <li>方式二：声明式，通过返回值描述「我要响应什么」，更符合 SpringMVC 的用法</li>
     * </ul>
     * <p>
     * 说明：讲义原文的方法签名里保留了一个没被用到的 {@code HttpServletResponse response} 形参，
     * 这里照抄保持一致，方便你和讲义对照。
     *
     * @param response 讲义原文保留了该形参（实际未使用）
     * @return 封装了状态码、响应头、响应体的 ResponseEntity 对象
     */
    @RequestMapping("/response2")
    public ResponseEntity<String> response2(HttpServletResponse response) throws IOException {
        return ResponseEntity
                .status(401)                          // 设置响应状态码
                .header("name", "itcast")            // 设置响应头
                .body("<h1>hello response</h1>");    // 设置响应体
    }

}

