package com.itheima.controller;

import com.itheima.dao.UserDao;
import com.itheima.service.UserService;
import jakarta.annotation.Resource;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * 【讲义 4.5 DI 详解】依赖注入的三种用法演示 + bean 名字验证。
 * <p>
 * ==================== 本类对应讲义哪一段？====================
 * <p>
 * 讲义 <b>4.5.1 @Autowired 用法</b> 与 <b>4.5.2 注意事项</b>。
 * <p>
 * 前面 {@code UserController3} 只演示了「属性注入」一种。而讲义 4.5.1 明确讲了三种：
 * <table border="1">
 *     <caption>@Autowired 进行依赖注入的三种常见方式</caption>
 *     <tr><th>方式</th><th>写法</th><th>优点</th><th>缺点</th></tr>
 *     <tr>
 *         <td><b>1. 属性注入</b></td>
 *         <td>字段上直接写 {@code @Autowired}</td>
 *         <td>代码简洁、方便快速开发</td>
 *         <td>隐藏了类之间的依赖关系、可能会破坏类的封装性</td>
 *     </tr>
 *     <tr>
 *         <td><b>2. 构造函数注入</b></td>
 *         <td>写在构造方法上（只有一个构造方法时可省略注解）</td>
 *         <td>能清晰地看到类的依赖关系、提高了代码的安全性</td>
 *         <td>代码繁琐、如果构造参数过多，可能会导致构造函数臃肿</td>
 *     </tr>
 *     <tr>
 *         <td><b>3. setter 注入</b></td>
 *         <td>写在 setter 方法上</td>
 *         <td>保持了类的封装性，依赖关系更清晰</td>
 *         <td>需要额外编写 setter 方法，增加了代码量</td>
 *     </tr>
 * </table>
 * <p>
 * 【讲义原文】在项目开发中，基于 {@code @Autowired} 进行依赖注入时，基本都是第一种和第二种方式。
 * 官方推荐第二种方式，因为会更加规范；但是在企业项目开发中，很多的项目中，
 * 也会选择第一种方式，因为更加简洁、高效（在规范性方面进行了妥协）。
 * <p>
 * ==================== 为什么把它们拆成三个类？====================
 * <p>
 * 三种方式在功能上完全等价，区别只在写法。但<b>同一个类里没法同时用三种方式注入同一个字段</b>，
 * 所以拆成三个 {@code @RestController} 静态内部类，各演示一种，方便逐个访问对比。
 * <p>
 * ==================== 本类的访问地址 ====================
 * <table border="1">
 *     <caption>演示地址</caption>
 *     <tr><th>地址</th><th>演示内容</th></tr>
 *     <tr><td><a href="http://localhost:8084/di/field">/di/field</a></td>
 *         <td>方式一：属性注入</td></tr>
 *     <tr><td><a href="http://localhost:8084/di/constructor">/di/constructor</a></td>
 *         <td>方式二：构造器注入（官方推荐）</td></tr>
 *     <tr><td><a href="http://localhost:8084/di/setter">/di/setter</a></td>
 *         <td>方式三：setter 注入</td></tr>
 *     <tr><td><a href="http://localhost:8084/di/byname">/di/byname</a></td>
 *         <td>4.5.2：按 bean 名字指定（{@code @Qualifier} / {@code @Resource}）</td></tr>
 *     <tr><td><a href="http://localhost:8084/di/daoname">/di/daoname</a></td>
 *         <td>4.5.2：Dao 层「同类型多个 bean」的三种指定方式</td></tr>
 * </table>
 * <p>
 * ==================== 对象从哪来？====================
 * <p>
 * 本类注入的是 {@code UserService} 类型，而容器里正好有一个 {@code UserService} 类型的 bean
 * （{@link com.itheima.service.impl.UserServiceImpl2}，因为它是唯一加了 {@code @Service} 的
 * Service 实现类）。
 * <p>
 * ⚠ 注意 {@link com.itheima.service.impl.UserServiceImpl} <b>故意没有加 {@code @Service}</b>，
 * 所以它不是 bean，容器里只有一个 UserService —— 这样 {@code @Autowired} 按类型注入不会歧义。
 * 如果你给 UserServiceImpl 也加上 {@code @Service}，启动就会报：
 * {@code required a single bean, but 2 were found}，那时就要用 4.5.2 的办法解决。
 */
public class DependencyInjectionController {

    // ========================================================================
    //  方式一：属性注入（最常用，代码最简洁）
    // ========================================================================

    /**
     * 访问 <a href="http://localhost:8084/di/field">http://localhost:8084/di/field</a>
     */
    @RestController
    public static class FieldInjectionController {

        /**
         * 属性注入：直接在字段上写 {@code @Autowired}。
         * <p>
         * 【讲义 4.5.1】优点：代码简洁、方便快速开发。
         * <br>缺点：隐藏了类之间的依赖关系、可能会破坏类的封装性。
         * <p>
         * 所谓「隐藏了依赖关系」是指：光看这个类的构造方法，看不出它依赖 UserService，
         * 必须翻到字段声明才知道。
         */
        @Autowired
        private UserService userService;   // 没有 new，对象由 Spring 容器注入

        @RequestMapping("/di/field")
        public String field() {
            List<?> users = userService.findAll();
            return "【方式一：属性注入】\n"
                    + "实际注入的 bean = " + userService.getClass().getSimpleName() + "\n"
                    + "查到 " + users.size() + " 条数据\n"
                    + "（写法：字段上直接写 @Autowired）";
        }
    }

    // ========================================================================
    //  方式二：构造器注入（官方推荐）
    // ========================================================================

    /**
     * 访问 <a href="http://localhost:8084/di/constructor">http://localhost:8084/di/constructor</a>
     */
    @RestController
    public static class ConstructorInjectionController {

        /**
         * 构造器注入：依赖通过构造方法的参数传进来。
         * <p>
         * 【讲义 4.5.1】优点：能清晰地看到类的依赖关系、提高了代码的安全性。
         * <br>缺点：代码繁琐、如果构造参数过多，可能会导致构造函数臃肿。
         * <p>
         * ① 字段用 {@code final} 修饰，一旦赋值就不能再改，更安全；
         * ② 但 final 字段必须在构造方法里赋值，所以必须写构造方法 —— 这就是它「代码繁琐」的地方。
         */
        private final UserService userService;

        /**
         * 构造方法。
         * <p>
         * 【讲义 4.5.1 注意】如果当前类中只存在一个构造方法，{@code @Autowired} 可以省略
         * （通常来说，也只有一个构造方法）。
         * <p>
         * 本类就只有一个构造方法，所以这里的 {@code @Autowired} 我<b>故意没写</b>，
         * 你加上也完全一样。
         */
        public ConstructorInjectionController(UserService userService) {
            this.userService = userService;
        }

        @RequestMapping("/di/constructor")
        public String constructor() {
            List<?> users = userService.findAll();
            return "【方式二：构造器注入】（官方推荐）\n"
                    + "实际注入的 bean = " + userService.getClass().getSimpleName() + "\n"
                    + "查到 " + users.size() + " 条数据\n"
                    + "（写法：依赖写在构造方法参数上，字段用 final；只有一个构造方法时 @Autowired 可省略）";
        }
    }

    // ========================================================================
    //  方式三：setter 注入
    // ========================================================================

    /**
     * 访问 <a href="http://localhost:8084/di/setter">http://localhost:8084/di/setter</a>
     */
    @RestController
    public static class SetterInjectionController {

        /**
         * 注意：这个字段<b>没有</b> {@code @Autowired}，注解写在下面的 setter 方法上。
         */
        private UserService userService;

        /**
         * setter 注入：{@code @Autowired} 写在 setter 方法上。
         * <p>
         * 【讲义 4.5.1】优点：保持了类的封装性，依赖关系更清晰。
         * <br>缺点：需要额外编写 setter 方法，增加了代码量。
         * <p>
         * Spring 在创建这个对象后，会调用这个 setter，把容器里的 UserService 传进来。
         */
        @Autowired
        public void setUserService(UserService userService) {
            this.userService = userService;
        }

        @RequestMapping("/di/setter")
        public String setter() {
            List<?> users = userService.findAll();
            return "【方式三：setter 注入】\n"
                    + "实际注入的 bean = " + userService.getClass().getSimpleName() + "\n"
                    + "查到 " + users.size() + " 条数据\n"
                    + "（写法：字段不加注解，@Autowired 写在 setter 方法上）";
        }
    }

    // ========================================================================
    //  讲义 4.5.2：按 bean 名字指定注入哪一个
    // ========================================================================

    /**
     * 访问 <a href="http://localhost:8084/di/byname">http://localhost:8084/di/byname</a>
     */
    @RestController
    public static class ByNameInjectionController {

        /** 只写 {@code @Autowired}，按类型注入 → 容器里只有一个 UserService，直接拿到它 */
        @Autowired
        private UserService defaultService;

        /**
         * 【方案二：@Qualifier】指定当前要注入的 bean 对象。
         * <p>
         * 【讲义 4.5.2 原文】在 {@code @Qualifier} 的 value 属性中，指定注入的 bean 的名称。
         * <b>{@code @Qualifier} 注解不能单独使用，必须配合 {@code @Autowired} 使用。</b>
         * <p>
         * ⚠ 关于 bean 名字怎么写，有个特别容易踩的坑：
         * <p>
         * 这里的名字必须写 <b>{@code userServiceImpl}</b>，
         * 而不是看起来更顺的 {@code userServiceImpl2}。为什么？
         * <p>
         * 因为 bean 的名字默认是<b>「类名首字母小写」</b>
         * （讲义 4.3.4.1 注意1：声明 bean 的时候，可以通过注解的 value 属性指定 bean 的名字，
         * 如果没有指定，默认为类名首字母小写）。
         * <p>
         * 而容器里这个 UserService bean 是
         * {@link com.itheima.service.impl.UserServiceImpl2}，它的类名首字母小写并不是
         * {@code userServiceImpl} —— 那为什么能匹配上？
         * <p>
         * 因为 {@code @Service} 没写 value 时，Spring 用「短类名首字母小写」，但
         * <b>更准确地说，Spring 生成的名字是 {@code userServiceImpl2}</b>。
         * 写成 {@code userServiceImpl} 会找不到 bean，启动直接失败：
         * <pre>
         * NoSuchBeanDefinitionException:
         *   No qualifying bean of type 'com.itheima.service.UserService' available:
         *   expected at least 1 bean which qualifies as autowire candidate.
         * </pre>
         * 所以在真实项目里，如果要用 {@code @Qualifier} 按名字指定，
         * <b>最稳的做法是给 {@code @Service} 显式写一个名字</b>：
         * <pre>
         * &#64;Service("userService")     // 显式指定 bean 名字，后面 @Qualifier("userService") 就能对上
         * public class UserServiceImpl2 implements UserService { ... }
         * </pre>
         * 本工程为了让讲义示例能跑通，这里直接写正确的名字 {@code userServiceImpl2}。
         */
        @Qualifier("userServiceImpl2")
        @Autowired
        private UserService serviceByQualifier;

        /**
         * 【方案三：@Resource】按照 bean 的名称进行注入。
         * <p>
         * 【讲义 4.5.2 原文】是按照 bean 的名称进行注入。通过 name 属性指定要注入的 bean 的名称。
         * <p>
         * 【讲义面试题】{@code @Autowired} 与 {@code @Resource} 的区别：
         * <ul>
         *     <li>{@code @Autowired} 是 <b>Spring 框架</b>提供的注解，
         *         而 {@code @Resource} 是 <b>JDK</b> 提供的注解
         *         （所以 import 的是 {@code jakarta.annotation.Resource}，不是 Spring 的包）</li>
         *     <li>{@code @Autowired} 默认按照<b>类型</b>注入，
         *         而 {@code @Resource} 按照<b>名称</b>注入</li>
         * </ul>
         * <p>
         * 补充：{@code @Resource} 也可以不写 name —— 那时它会先按<b>字段名</b>去容器里找同名的 bean，
         * 找不到再退化成按类型注入。这里显式写了 name，意图更清楚。
         */
        @Resource(name = "userServiceImpl2")
        private UserService serviceByResource;

        @RequestMapping("/di/byname")
        public String byName() {
            StringBuilder sb = new StringBuilder();
            sb.append("【讲义 4.5.2：按 bean 名字指定注入哪一个】\n\n");
            sb.append("容器里 UserService 类型的 bean 只有 1 个，所以下面三种写法取到的是同一个对象：\n\n");

            sb.append("1) @Autowired（按类型）                    → ")
                    .append(defaultService.getClass().getSimpleName()).append("\n");
            sb.append("2) @Qualifier(\"userServiceImpl2\")  + @Autowired → ")
                    .append(serviceByQualifier.getClass().getSimpleName()).append("\n");
            sb.append("3) @Resource(name = \"userServiceImpl2\")        → ")
                    .append(serviceByResource.getClass().getSimpleName()).append("\n");

            List<?> users = defaultService.findAll();
            sb.append("\n都能查到 ").append(users.size()).append(" 条数据。\n\n");

            sb.append("【bean 名字规则】声明 bean 时如未指定 value，默认是「类名首字母小写」：\n");
            sb.append("  UserServiceImpl2 → userServiceImpl2\n");
            sb.append("  UserDaoImpl2     → userDaoImpl2\n\n");
            sb.append("⚠ 名字写错不会「返回 null」，而是启动时直接失败（NoSuchBeanDefinitionException）。\n");
            sb.append("  所以想按名字注入时，建议给注解显式起名，如 @Service(\"userService\")。\n\n");
            sb.append("👉 想看「同类型多个 bean」的真实效果，请访问 /di/daoname");

            return sb.toString();
        }
    }

    // ========================================================================
    //  讲义 4.5.2：同类型多个 bean 的真实场景（Dao 层）
    // ========================================================================

    /**
     * 访问 <a href="http://localhost:8084/di/daoname">http://localhost:8084/di/daoname</a>
     * <p>
     * 这个类演示「同类型多个 bean」在 Dao 层的真实场景 ——
     * 本工程里 Dao 层<b>真的有两个</b> bean：
     * <ul>
     *     <li>{@code userDaoImpl}  —— {@link com.itheima.dao.impl.UserDaoImpl}</li>
     *     <li>{@code userDaoImpl2} —— {@link com.itheima.dao.impl.UserDaoImpl2}（带 {@code @Primary}）</li>
     * </ul>
     * 两个都加了 {@code @Repository} 交给容器，所以 {@code @Autowired} 按类型注入时会发现两个候选，
     * 必须有一个「默认选择」—— 这就是 {@code @Primary} 的作用。
     * <p>
     * 而 Service 层没有这个问题，因为 {@code UserServiceImpl} 故意没加 {@code @Service}，
     * 容器里只有一个 UserService。
     */
    @RestController
    public static class DaoBeanNameController {

        /**
         * 只写 {@code @Autowired}，不指定名字 → 走 {@code @Primary} 那个（userDaoImpl2）。
         * <p>
         * 【讲义 4.5.2 方案一】当存在多个相同类型的 Bean 注入时，加上 {@code @Primary} 注解，
         * 来确定默认的实现。
         */
        @Autowired
        private UserDao defaultDao;

        /** 用 {@code @Resource} 按名字指定 → 注入 {@code userDaoImpl} */
        @Resource(name = "userDaoImpl")
        private UserDao daoByName1;

        /** 用 {@code @Qualifier} 按名字指定 → 注入 {@code userDaoImpl2} */
        @Qualifier("userDaoImpl2")
        @Autowired
        private UserDao daoByName2;

        @RequestMapping("/di/daoname")
        public String daoName() {
            return "【Dao 层：同类型多个 bean 的三种指定方式】\n\n"
                    + "容器里有两个 UserDao：userDaoImpl、userDaoImpl2（后者带 @Primary）\n\n"
                    + "方案一 @Autowired（按类型）        → " + defaultDao.getClass().getSimpleName()
                    + "   ← @Primary 指定的默认实现\n"
                    + "方案三 @Resource(name=\"userDaoImpl\") → " + daoByName1.getClass().getSimpleName() + "\n"
                    + "方案二 @Qualifier(\"userDaoImpl2\")    → " + daoByName2.getClass().getSimpleName() + "\n\n"
                    + "三种方式取到的都是同一批数据（都读 user.txt），"
                    + "但注入的「对象」不同 —— 这就是「同类型多 bean」怎么指定用哪个。\n\n"
                    + "⚠ 如果两个 Dao 都不加 @Primary，启动就会报：\n"
                    + "   required a single bean, but 2 were found";
        }
    }

}

package com.itheima.controller;

import cn.hutool.core.io.IoUtil;
import cn.hutool.json.JSONConfig;
import cn.hutool.json.JSONUtil;
import com.itheima.pojo.User;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 用户列表案例 —— 控制层（未分层版）
 * <p>
 * ==================== 本类对应讲义哪一段？====================
 * <p>
 * 讲义《04-Web后端基础(基础知识)》<b>3.2 代码实现</b>里那张代码块：
 * <blockquote>
 * 【讲义原文】在 {@code com.itheima} 包下新建一个子包 {@code controller}，在其中创建一个 {@code UserController}
 * </blockquote>
 * <p>
 * ==================== 本类在干什么？====================
 * <p>
 * 【讲义 3.1 需求】基于 SpringBoot 开发 web 程序，完成用户列表的渲染展示。
 * 当在浏览器地址栏，访问前端静态页面（{@code http://localhost:8084/user.html}）后，
 * 在前端页面上，会发送 ajax 请求，请求服务端（{@code http://localhost:8084/list}），
 * 服务端程序加载 {@code user.txt} 文件中的数据，读取出来后最终给前端页面响应 json 格式的数据，
 * 前端页面再将数据渲染展示在表格中。
 * <p>
 * ==================== ⚠ 本类是「反面教材」，别急着吐槽它乱 ====================
 * <p>
 * 看下面的 {@link #list()} 方法：<b>读文件、解析数据、响应数据，全堆在一个方法里了</b>。
 * <p>
 * 【讲义 3.4 问题分析原文】上述案例的功能，我们虽然已经实现，但是呢，我们会发现案例中：
 * 解析文本文件中的数据，处理数据的逻辑代码，给页面响应的代码全部都堆积在一起了，
 * 全部都写在 controller 方法中了。
 * <ul>
 *     <li>当我们要修改操作数据部分的代码，需要改动 Controller</li>
 *     <li>当我们要完善逻辑处理部分的代码，需要改动 Controller</li>
 *     <li>当我们需要修改数据响应的代码，还是需要改动 Controller</li>
 * </ul>
 * 这样呢，就会造成我们整个工程代码的复用性比较差，而且代码难以维护。
 * <p>
 * 那如何解决这个问题呢？【讲义原文】其实在现在的开发中，有非常成熟的解决思路，
 * 那就是<b>分层开发</b> —— 也就是讲义第 4 章要讲的「分层解耦」：
 * <ul>
 *     <li>三层架构版 → {@link UserController2}（访问 {@code /user2}）</li>
 *     <li>IOC 解耦版 → {@link UserController3}（访问 {@code /user3}）</li>
 * </ul>
 * <p>
 * <b>建议的阅读顺序：先看懂本类的「乱」→ 再看 UserController2「分层」→ 最后看 UserController3「解耦」</b>，
 * 这样能体会到每一步分别在解决什么问题。
 * <p>
 * ==================== 关于三个 UserController 的说明 ====================
 * <p>
 * 讲义里这个类在 3.2、4.1.2、4.3 三个阶段都出现过（每次都是「改这个类」）。
 * 但同一个工程里不能有三个同名的 {@code UserController.java}，所以本工程把它们做成三个类：
 * <table border="1">
 *     <caption>三个类与讲义章节的对应</caption>
 *     <tr><th>本工程的类</th><th>对应讲义</th><th>访问地址</th><th>特点</th></tr>
 *     <tr><td>{@code UserController}（本类）</td><td>3.2 案例</td><td>{@code /list}</td>
 *         <td>全堆在一起（未分层）</td></tr>
 *     <tr><td>{@code UserController2}</td><td>4.1.2 三层架构</td><td>{@code /user2}</td>
 *         <td>分了 Controller/Service/Dao 三层，但对象还是 new 的</td></tr>
 *     <tr><td>{@code UserController3}</td><td>4.3 IOC&amp;DI</td><td>{@code /user3}</td>
 *         <td>用 {@code @Autowired} 注入，彻底解耦</td></tr>
 * </table>
 * <b>方法体里的代码与讲义逐字一致</b>，只多了注释；路径不同只是为了三个版本能同时跑起来对比。
 */
@RestController
public class UserController {

    /**
     * 查询所有用户，并以 JSON 格式响应给前端页面。
     * <p>
     * 访问地址：<a href="http://localhost:8084/list">http://localhost:8084/list</a>
     * <p>
     * ==================== 返回值为什么能自动变成 JSON？====================
     * <p>
     * 【讲义 3.3 原文】controller 方法中的 return 的结果，怎么就可以响应给浏览器呢？
     * 答案：使用 {@code @ResponseBody} 注解。
     * <p>
     * 而我们在类上加的 {@code @RestController} 注解，是由两个注解组合起来的：
     * {@code @Controller} + {@code @ResponseBody}。
     * 也就是说类上已经加了 {@code @ResponseBody} 注解了，
     * 而一旦在类上加了 {@code @ResponseBody} 注解，就相当于该类所有的方法中都已经添加了它。
     * <p>
     * 【讲义 3.3】{@code @ResponseBody} 注解的作用：
     * <b>将方法返回值直接响应给浏览器，如果返回值类型是实体对象/集合，
     * 将会转换为 JSON 格式后再响应给浏览器。</b>
     * <p>
     * 所以本方法返回 {@code List<User>}，SpringMVC 会自动用 Jackson 转成 JSON，浏览器收到的就是：
     * <pre>
     * [{"id":1,"username":"daqiao","password":"1234567890","name":"大乔","age":22,"updateTime":"2024-07-15 15:05:45"}, ...]
     * </pre>
     * <p>
     * 💡 前后端分离的项目中，一般直接在请求处理类上加 {@code @RestController}，
     * 就无需在方法上加 {@code @ResponseBody} 了。
     *
     * @return 用户列表，会被自动转成 JSON 响应给浏览器
     */
    @RequestMapping("/list")
    public List<User> list() {

        // ==================== 1.加载并读取文件 ====================
        // getClassLoader().getResourceAsStream("user.txt")
        //   从「类路径」下读取 user.txt 文件，得到一个字节输入流。
        //
        // ⚠ 为什么路径只写 "user.txt" 而不写 "src/main/resources/user.txt"？
        //   Maven 会把 src/main/resources 下的文件复制到 target/classes，
        //   而 target/classes 就在类路径上，所以直接从类路径根目录按文件名找即可。
        //   写成带 src/... 的路径，打包成 jar 之后就找不到文件了（那是文件系统路径）。
        InputStream in = this.getClass().getClassLoader().getResourceAsStream("user.txt");

        // 用 Hutool 提供的 IoUtil.readLines(...) 一次性把输入流按行读完。
        // 三个参数分别是：输入流、字符编码(UTF-8，防止中文乱码)、接收结果的集合。
        // 得到的 lines 里，每个元素就是 user.txt 里的一行文本。
        ArrayList<String> lines = IoUtil.readLines(in, StandardCharsets.UTF_8, new ArrayList<>());

        // ==================== 2.解析数据，封装成对象 --> 集合 ====================
        // 每一行的格式是（逗号分隔）：
        //   1,daqiao,1234567890,大乔,22,2024-07-15T15:05:45
        //   ↑    ↑        ↑      ↑   ↑          ↑
        //   id username password name age    updateTime
        //
        // lines.stream().map(...) 是 Java 8 的流式写法，等价于下面这段 for 循环：
        //   List<User> userList = new ArrayList<>();
        //   for (String line : lines) {
        //       String[] parts = line.split(",");
        //       ... 同样解析出 6 个字段
        //       userList.add(new User(id, username, password, name, age, updateTime));
        //   }
        List<User> userList = lines.stream().map(line -> {

            // 按逗号把这一行切成 6 段
            String[] parts = line.split(",");

            // 按位置依次取出每一段，并转换成对应的类型
            Integer id = Integer.parseInt(parts[0]);      // 第 0 段：id，字符串要转成 Integer
            String username = parts[1];                   // 第 1 段：用户名
            String password = parts[2];                   // 第 2 段：密码
            String name = parts[3];                       // 第 3 段：姓名
            Integer age = Integer.parseInt(parts[4]);     // 第 4 段：年龄

            // 第 5 段是时间字符串，例如 "2024-07-15T15:05:45"
            // 用 DateTimeFormatter 指定格式，把它解析成 LocalDateTime 对象。
            // 注意这里是 'T'（带单引号表示 T 是字面量字符，不是格式符），
            // 因为文件里存的就是 ISO 格式（年月日与时分秒之间用 T 分隔）。
            LocalDateTime updateTime = LocalDateTime.parse(parts[5],
                    DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss"));

            // 用 Lombok 的 @AllArgsConstructor 生成的全参构造方法创建 User 对象
            return new User(id, username, password, name, age, updateTime);

        }).collect(Collectors.toList());   // 把流重新收集回 List

        // ==================== 3.响应数据 ====================
        // 返回 List<User>，配合类上的 @RestController（内含 @ResponseBody），
        // SpringMVC 会自动把集合转成 JSON 字符串再响应给浏览器 —— 无需手动转 JSON。
        //
        // 【讲义原文】代码块里还有一行被注释掉的「手动转 JSON」写法：
        //
        //     //return JSONUtil.toJsonStr(userList, JSONConfig.create().setDateFormat("yyyy-MM-dd HH:mm:ss"));
        //     return userList;
        //
        // 那种写法要求方法返回值类型是 String。本工程把它做成了可直接访问的对照接口，
        // 见下面的 listManual()，可以分别访问 /list 和 /list-manual 对比输出。
        return userList;
    }

    /**
     * 【对照接口】讲义 3.2 里「手动转 JSON」的写法。
     * <p>
     * 访问地址：<a href="http://localhost:8084/list-manual">http://localhost:8084/list-manual</a>
     * <p>
     * 讲义代码块里被注释掉的那一行就是它：
     * <pre>
     * return JSONUtil.toJsonStr(userList, JSONConfig.create().setDateFormat("yyyy-MM-dd HH:mm:ss"));
     * </pre>
     * <p>
     * ==================== 两种转 JSON 的方式对比 ====================
     * <table border="1">
     *     <caption>自动转 JSON vs 手动转 JSON</caption>
     *     <tr><th></th><th>自动（推荐）</th><th>手动</th></tr>
     *     <tr><td>方法返回值</td><td>{@code List<User>}</td><td>{@code String}</td></tr>
     *     <tr><td>谁来转</td><td>SpringMVC 内置的 Jackson</td><td>Hutool 的 JSONUtil</td></tr>
     *     <tr><td>日期格式怎么控制</td><td>{@code User} 字段上的 {@code @JsonFormat} 注解</td>
     *         <td>{@code JSONConfig.setDateFormat(...)}</td></tr>
     *     <tr><td>访问地址</td><td>{@code /list}</td><td>{@code /list-manual}</td></tr>
     * </table>
     * 两个接口返回的 JSON 内容是一样的，可以分别访问对比。
     * <p>
     * ⚠ 小知识点：方法返回值是 String，SpringMVC 会把它<b>原样写出</b>，不会再加一层引号，
     * 所以浏览器看到的仍然是标准的 JSON 数组。
     *
     * @return 手动转换好的 JSON 字符串
     */
    @RequestMapping("/list-manual")
    public String listManual() {
        InputStream in = this.getClass().getClassLoader().getResourceAsStream("user.txt");
        ArrayList<String> lines = IoUtil.readLines(in, StandardCharsets.UTF_8, new ArrayList<>());

        List<User> userList = lines.stream().map(line -> {
            String[] parts = line.split(",");
            Integer id = Integer.parseInt(parts[0]);
            String username = parts[1];
            String password = parts[2];
            String name = parts[3];
            Integer age = Integer.parseInt(parts[4]);
            LocalDateTime updateTime = LocalDateTime.parse(parts[5],
                    DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss"));
            return new User(id, username, password, name, age, updateTime);
        }).collect(Collectors.toList());

        // 这就是讲义 3.2 代码块里被注释掉的那一行：
        // 用 Hutool 手动把 List 转成 JSON 字符串，并指定日期格式为 yyyy-MM-dd HH:mm:ss
        return JSONUtil.toJsonStr(userList, JSONConfig.create().setDateFormat("yyyy-MM-dd HH:mm:ss"));
    }

}

