package com.itheima.dao.impl;

import cn.hutool.core.io.IoUtil;
import com.itheima.dao.UserDao;
import org.springframework.stereotype.Repository;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * 用户数据访问层实现类（三层架构版）
 * <p>
 * 【讲义 4.1.2 原文】在 com.itheima.dao.impl 中创建 UserDaoImpl，代码如下。
 * <p>
 * ======================== 这段代码在干什么？========================
 * <p>
 * 把 {@code src/main/resources/user.txt} 文件读出来，每一行放到一个 List 里返回。
 * <p>
 * 关键点：<b>为什么用 getResourceAsStream("user.txt") 就能读到文件？</b>
 * <p>
 * 因为 Maven 会把 {@code src/main/resources} 下的文件复制到编译输出目录
 * {@code target/classes} 里，这个目录就在「类路径（classpath）」上。
 * {@code getClass().getClassLoader().getResourceAsStream("user.txt")} 就是从类路径根目录找 user.txt。
 * <p>
 * 所以文件路径写的是 {@code "user.txt"} 而不是 {@code "src/main/resources/user.txt"}——
 * <b>不要写错成带路径的形式</b>，那是文件系统路径，打包成 jar 之后就找不到文件了。
 * <p>
 * ======================== ⚠ 关于本类上的 @Repository ========================
 * <p>
 * 讲义 4.1.2 阶段这个类是没有注解的（那时 Dao 对象由 Service 自己 {@code new}）。
 * 本工程给它加上了 {@code @Repository}，只要把它<b>注释掉或删掉</b>，
 * 就能回到讲义 4.1.2 的原始状态（{@link com.itheima.service.impl.UserServiceImpl} 里
 * 依然是自己 new 对象，不依赖 Spring 容器）。
 * <p>
 * 加上它的原因是：<b>讲义 4.5.2 要讲的「同类型多个 bean」在 Dao 层是真实存在的</b>。
 * 本类（bean 名 {@code userDaoImpl}）与 {@link UserDaoImpl2}（bean 名 {@code userDaoImpl2}）
 * 都交给了容器，于是 {@code @Autowired} 按类型注入时会发现有两个 UserDao 可选，
 * 这才需要 {@code UserDaoImpl2} 上的 {@code @Primary} 来指定默认用哪个。
 * <p>
 * 如果本类不加注解，容器里就只有一个 UserDao，{@code @Primary} 就成了空操作，
 * 讲义 4.5.2 讲的那个报错场景在这个工程里就复现不出来了。
 */
@Repository
public class UserDaoImpl implements UserDao {

    @Override
    public List<String> findAll() {
        // 1.从类路径下读取 user.txt 文件（得到一个字节输入流）
        InputStream in = this.getClass().getClassLoader().getResourceAsStream("user.txt");

        // 2.用 Hutool 工具类 IoUtil 把输入流按 UTF-8 逐行读取，装进一个 ArrayList
        //    参数含义：输入流、字符编码、装结果的集合
        ArrayList<String> lines = IoUtil.readLines(in, StandardCharsets.UTF_8, new ArrayList<>());

        // 3.返回原始文本行，交给 Service 层去解析
        return lines;
    }

}

