package com.itheima.service.impl;

import com.itheima.dao.UserDao;
import com.itheima.dao.impl.UserDaoImpl;
import com.itheima.pojo.User;
import com.itheima.service.UserService;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 用户业务逻辑层实现类（三层架构版）
 * <p>
 * 【讲义 4.1.2 原文】在 com.itheima.service.impl 中创建 UserServiceImpl，代码如下。
 * <p>
 * ======================== 这段代码在干什么？========================
 * <p>
 * 把 Dao 层拿到的「一堆文本行」解析成「一堆 User 对象」。
 * <p>
 * 一行文本长这样（逗号分隔）：
 * <pre>
 * 1,daqiao,1234567890,大乔,22,2024-07-15T15:05:45
 * ↑    ↑        ↑      ↑   ↑          ↑
 * id username password name age    updateTime
 * </pre>
 * <p>
 * 解析用到了 Java 8 的 <b>Stream 流</b>，这是企业开发里非常常用的写法，等价于下面这种 for 循环：
 * <pre>
 * List&lt;User&gt; userList = new ArrayList&lt;&gt;();
 * for (String line : lines) {
 *     String[] parts = line.split(",");
 *     // ... 逐个字段解析
 *     userList.add(new User(id, username, password, name, age, updateTime));
 * }
 * return userList;
 * </pre>
 * 流式写法更简洁，你两种都可以用，理解其中一种即可。
 * <p>
 * ======================== ⚠ 本类也有个「耦合」问题 ========================
 * <p>
 * 注意第 34 行：{@code private UserDao userDao = new UserDaoImpl();}
 * <p>
 * 这里是<b>程序员自己 new 对象</b>。讲义 4.2.1 说的「层与层之间耦合」指的就是这个：
 * Service 层写死了要用 UserDaoImpl，将来要换成别的实现类，就得改这一行代码。
 * <p>
 * 怎么解耦？—— 用 IOC/DI，见同包下的 {@link UserServiceImpl2}。
 */
public class UserServiceImpl implements UserService {

    /**
     * ⚠ 这里是 new 出来的，不是注入的 —— 这就是「耦合」
     * <p>
     * 讲义 4.2.1 翻译：如果说我们需要更换实现类，
     * 比如由于业务的变更，UserDaoImpl 不能满足现有的业务需求，
     * 我们需要切换为另外一套实现，就需要修改这里的代码。
     */
    private UserDao userDao = new UserDaoImpl();

    @Override
    public List<User> findAll() {
        // 第一步：调用 Dao 层，拿到原始的文本行
        List<String> lines = userDao.findAll();

        // 第二步：解析数据，把「一行文本」封装成「一个 User 对象」，最终得到一个集合
        List<User> userList = lines.stream()          // 把 List<String> 变成流
                .map(line -> {                        // map：把每一行文本「映射」成一个 User 对象
                    // 按逗号切分这一行，得到 6 段内容
                    String[] parts = line.split(",");

                    // 按位置取出每一段，并转成对应的类型
                    Integer id = Integer.parseInt(parts[0]);            // 第 0 段：id，字符串要转 Integer
                    String username = parts[1];                          // 第 1 段：用户名
                    String password = parts[2];                          // 第 2 段：密码
                    String name = parts[3];                              // 第 3 段：姓名
                    Integer age = Integer.parseInt(parts[4]);            // 第 4 段：年龄

                    // 第 5 段：时间字符串 "2024-07-15T15:05:45"
                    // 用 DateTimeFormatter 指定格式，把它解析成 LocalDateTime 对象
                    LocalDateTime updateTime = LocalDateTime.parse(parts[5],
                            DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss"));

                    // 用 Lombok 的 @AllArgsConstructor 生成的全参构造方法创建对象
                    return new User(id, username, password, name, age, updateTime);
                })
                .collect(Collectors.toList());        // collect：把流重新收集回 List

        // 第三步：把解析好的用户列表返回给 Controller 层
        return userList;
    }

}

package com.itheima.service.impl;

import com.itheima.dao.UserDao;
import com.itheima.pojo.User;
import com.itheima.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 用户业务逻辑层实现类（IOC &amp; DI 解耦版）
 * <p>
 * 【讲义 4.3 原文】2). 为 Controller 及 Service 注入运行时所依赖的对象。
 * 在实现类加上 {@code @Service} 注解声明 Service 层的 bean，用 {@code @Autowired} 完成依赖注入。
 * <p>
 * ======================== 与 UserServiceImpl 的两处关键差别 ========================
 * <p>
 * <b>差别一：类上多了 {@code @Service}</b>
 * <p>
 * 意思是将这个类的对象交给 IOC 容器管理。bean 名字默认是类名首字母小写 → {@code userServiceImpl2}。
 * <p>
 * <b>差别二：Dao 字段不是 new 出来的，而是 {@code @Autowired} 注入的</b>
 * <p>
 * 对比一下：
 * <pre>
 * // UserServiceImpl（耦合版）
 * private UserDao userDao = new UserDaoImpl();      // 写死了，换实现就要改这里
 *
 * // UserServiceImpl2（解耦版）
 * &#64;Autowired
 * private UserDao userDao;                          // 由容器决定给哪个实现，这里不用改
 * </pre>
 * <p>
 * 这就是讲义 4.2.2 讲的 <b>IOC（控制反转）</b>和 <b>DI（依赖注入）</b>：
 * <ul>
 *     <li><b>控制反转</b>：对象的创建控制权由程序自身转移到外部（容器）。
 *         以前是「我要什么对象我自己 new」，现在是「容器帮我 new 好，放那儿等我拿」。</li>
 *     <li><b>依赖注入</b>：容器为应用程序提供运行时所需要的资源。
 *         本类运行时需要 UserDao，容器就给它注入一个 UserDao。</li>
 * </ul>
 * <p>
 * 容器里创建、管理的对象，就叫做 <b>bean 对象</b>。
 * <p>
 * ======================== @Autowired 是怎么找到对象的？========================
 * <p>
 * 【讲义 4.5 原文】{@code @Autowired} 注解，默认是按照<b>类型</b>进行自动装配的
 * （去 IOC 容器中找某个类型的对象，然后完成注入操作）。
 * <p>
 * 本类的字段类型是 {@code UserDao}，容器里正好有 {@code userDaoImpl} 和 {@code userDaoImpl2}
 * 两个 UserDao 类型的 bean —— 这就出现「同类型多个 bean」的问题了。
 * 解决方式是 {@link com.itheima.dao.impl.UserDaoImpl2} 上的 {@code @Primary}：
 * 告诉容器「默认优先注入我」，于是这里注入的实际是 userDaoImpl2。
 * <p>
 * 如果想明确指定注入某一个，可以用 {@code @Qualifier("userDaoImpl")}
 * 或 {@code @Resource(name = "userDaoImpl")}（讲义 4.5.2 方案二、三）。
 */
@Service
public class UserServiceImpl2 implements UserService {

    /**
     * 依赖注入：容器会为本字段提供一个 UserDao 类型的 bean
     * <p>
     * 注意这里<b>没有 new</b>，字段也没有初始化 —— 对象是 Spring 启动时帮你塞进来的。
     */
    @Autowired
    private UserDao userDao;

    @Override
    public List<User> findAll() {
        // 第一步：调用 Dao 层拿原始文本行（这里调用的是被注入进来的那个 Dao 对象）
        List<String> lines = userDao.findAll();

        // 第二步：解析数据，封装成对象 --> 集合（与 UserServiceImpl 里的解析逻辑完全相同）
        List<User> userList = lines.stream().map(line -> {
            String[] parts = line.split(",");
            Integer id = Integer.parseInt(parts[0]);
            String username = parts[1];
            String password = parts[2];
            String name = parts[3];
            Integer age = Integer.parseInt(parts[4]);
            LocalDateTime updateTime = LocalDateTime.parse(parts[5],
                    DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss"));
            return new User(id, username, password, name, age, updateTime);
        }).collect(Collectors.toList());

        // 第三步：返回给 Controller
        return userList;
    }

}
